window.STUDY={"title":"FLFR Lieutenant Exam","updated":"2026-11-01","sources":[{"id":"flfr26","name":"FLFR EMS Protocols 2026","version":"26.1.2","effective":"01/01/2026"}],"decks":[{"id":"s01","name":"1 · General Information"},{"id":"s02","name":"2 · Medical"},{"id":"s03","name":"3 · Respiratory"},{"id":"s04","name":"4 · Cardiac Emergencies"},{"id":"s05","name":"5 · Cardiac Arrest"},{"id":"s06","name":"6 · Trauma"},{"id":"s07","name":"7 · Trauma Resuscitation"},{"id":"s08","name":"8 · Overdose"},{"id":"s09","name":"9 · Restraint & Pain"},{"id":"s10","name":"10 · Environmental"},{"id":"s11","name":"11 · Obstetrical"},{"id":"s12","name":"12 · Procedures"},{"id":"s13","name":"13 · Pharmacology"},{"id":"s14","name":"14 · HazMat"},{"id":"s15","name":"15 · QA & Improvement"},{"id":"s16","name":"16 · What's New in 2026"}],"cards":[{"id":"s01c01","front":"Protocol deviation: who can deviate and what follows?","back":"Two concurring paramedics, documented, EMS Officer consulted. Notify EMS Division and Medical Director in writing; QA/QI review.","page":27,"deck":"s01"},{"id":"s01c02","front":"Florida Incapacitated Persons Act statute number?","back":"401.445.","page":28,"deck":"s01"},{"id":"s01c03","front":"Two conditions to apply the Incapacitated Persons Act?","back":"A medical emergency is present and the patient lacks capacity. No unreasonable force.","page":29,"deck":"s01"},{"id":"s01c04","front":"How is capacity judged in the field?","back":"The patient's ability to understand and articulate the risks of refusal.","page":29,"deck":"s01"},{"id":"s01c05","front":"OPQRST(A) for HPI?","back":"Onset, Palliative/Provoke/Previous, Quality, Radiation, Severity, Time, Associated.","page":30,"deck":"s01"},{"id":"s01c06","front":"NPA vs OPA rule?","back":"Semi-conscious with gag: NPA. Unresponsive without gag: OPA. Ventilating over 2 min (adult): SGA or ETT.","page":31,"deck":"s01"},{"id":"s01c07","front":"Child with fever, drooling or stridor in distress: airway rule?","back":"No NPA or OPA. Don't stress the patient.","page":31,"deck":"s01"},{"id":"s01c08","front":"Oxygen targets?","back":"SpO2 95% general, cardiac, stroke; 90% COPD/asthma. TBI and 3rd-trimester trauma: 15 L NRB.","page":32,"deck":"s01"},{"id":"s01c09","front":"ETT placement is confirmed by?","back":"Seeing the tube pass the cords, auscultation, and continuous EtCO2.","page":32,"deck":"s01"},{"id":"s01c10","front":"Ventilation rates by age?","back":"Adult 10/min with or without pulse. Child 20/min with a pulse, 10/min without. Neonate 40/min.","page":32,"deck":"s01"},{"id":"s01c11","front":"Who gets EtCO2 nasal cannula monitoring?","back":"Respiratory distress, AMS, sedated/pain meds, ketamine, seizures, ventilatory support, all ALERT patients.","page":33,"deck":"s01"},{"id":"s01c12","front":"12-lead: who and how often?","back":"Any possible cardiac symptoms (pain, palpitations, syncope, weakness, SOB, diaphoresis). Repeat every 5 min and on ROSC.","page":33,"deck":"s01"},{"id":"s01c13","front":"Vital sign frequency by priority?","back":"Priority 3: at least 2 sets, every 15 min. Priority 2: every 5 min.","page":34,"deck":"s01"},{"id":"s01c14","front":"Adult hypotension definition in these protocols?","back":"SBP under 100.","page":34,"deck":"s01"},{"id":"s01c15","front":"Pediatric patient definition for EMS protocols?","back":"Absence of puberty (breast development; underarm/chest/facial hair).","page":34,"deck":"s01"},{"id":"s01c16","front":"Pediatric vs adult: medical ED and trauma alert ages?","back":"Medical ED: 17 or younger is peds. Trauma alert adult: 16+ at Broward Health, 15+ at Memorial Regional.","page":34,"deck":"s01"},{"id":"s01c17","front":"Patient priorities 1–3?","back":"1: cardiac, trauma or respiratory arrest. 2: unstable, life-threatening. 3: stable.","page":35,"deck":"s01"},{"id":"s01c18","front":"Freestanding EDs?","back":"Never transport to a freestanding ED.","page":35,"deck":"s01"},{"id":"s01c19","front":"OB trauma alert destination?","back":"Closest of Memorial Regional or BHMC.","page":35,"deck":"s01"},{"id":"s01c20","front":"STEMI alert ECG time targets?","back":"12-lead within 5 min of contact, transmitted within 10 min.","page":36,"deck":"s01"},{"id":"s01c21","front":"STEMI: when to fly?","back":"If ground time to the closest STEMI facility is over 20 min: air (if available) to a STEMI facility with surgical backup.","page":36,"deck":"s01"},{"id":"s01c22","front":"Stroke alert destination?","back":"Thrombectomy-capable facility or comprehensive stroke center.","page":36,"deck":"s01"},{"id":"s01c23","front":"EMTALA and helipads?","back":"A helicopter landing within 250 yards of a hospital does not trigger EMTALA.","page":37,"deck":"s01"},{"id":"s01c24","front":"Trauma patient arrests in front of crews: destination?","back":"Closest appropriate trauma center.","page":37,"deck":"s01"},{"id":"s01c25","front":"Intubated 911 interfacility transfers: requirement?","back":"Must be paralyzed and sedated by the sending facility; if refused, contact the BC or EMS supervisor.","page":37,"deck":"s01"},{"id":"s01c26","front":"Psychiatric patient destination?","back":"Closest appropriate ED, regardless of psych capability.","page":38,"deck":"s01"},{"id":"s01c27","front":"Helicopter criteria (name 4)?","back":"Trauma scorecard criteria, ground to trauma center over 20 min, extrication over 15 min, ground response over 10 min, MCI, whole blood needs.","page":38,"deck":"s01"},{"id":"s01c28","front":"When will the helicopter NOT be used?","back":"Unsafe per crew, bariatric per pilot, uncontrolled combative patient, HazMat-contaminated, prisoner (per crew).","page":38,"deck":"s01"},{"id":"s01c29","front":"Florida Abuse Hotline and what to document?","back":"1-866-LE-ABUSE. Call taker name, ID number and time called.","page":40,"deck":"s01"},{"id":"s01c30","front":"Abuse: who is notified first?","back":"EMS Supervisor or Battalion Chief (transported or not), then the receiving hospital. Email FLFREMS@fortlauderdale.gov.","page":41,"deck":"s01"},{"id":"s01c31","front":"When is a DNRO in force?","back":"Only when the patient is in cardiac arrest. A living will is not covered.","page":42,"deck":"s01"},{"id":"s01c32","front":"Valid DNRO?","back":"Yellow DH Form 1896 original, or a yellow copy, with original signatures. Phone or oral orders are not valid.","page":42,"deck":"s01"},{"id":"s01c33","front":"DNRO validity in doubt?","back":"Start resuscitation. Law enforcement cannot refuse resuscitation for the patient.","page":42,"deck":"s01"},{"id":"s01c34","front":"DNRO identity confirmation?","back":"Photo ID or a witness (name, address, phone, relationship documented). Photograph the DNRO for the report.","page":43,"deck":"s01"},{"id":"s01c35","front":"Out-of-state DNRO?","back":"Contact medical control for orders to withhold resuscitation.","page":43,"deck":"s01"},{"id":"s01c36","front":"When does someone become a patient?","back":"Anytime an assessment or procedure is done, including lift assists.","page":45,"deck":"s01"},{"id":"s01c37","front":"Capacity vs competency?","back":"Capacity: medical, judged by the paramedic. Competency: legal, decided by a judge.","page":46,"deck":"s01"},{"id":"s01c38","front":"Who CANNOT refuse care?","back":"Minors, altered LOC, suicidal/homicidal, cognitive deficits, conditions impairing reasoning.","page":46,"deck":"s01"},{"id":"s01c39","front":"Capacity checklist for a refusal?","back":"AAOx4 and GCS 15, not under the influence, not suicidal/homicidal, no condition impairing decisions.","page":48,"deck":"s01"},{"id":"s01c40","front":"Who cannot refuse transport after treatment?","back":"Anyone given drugs affecting mental status/breathing, cardiovascular drugs, or Narcan for a suspected OD.","page":50,"deck":"s01"},{"id":"s01c41","front":"Who may sign a refusal for a minor?","back":"A parent/legal guardian or a law enforcement officer. Phone refusals need an LEO witness signature.","page":51,"deck":"s01"},{"id":"s01c42","front":"Emancipated minor in Florida?","back":"At least 16 and married, enlisted, or court-ordered. A pregnant minor may consent to pregnancy-related care.","page":51,"deck":"s01"},{"id":"s01c43","front":"AT&T Language Line?","back":"1-877-287-6794. Use 911 as the ID; document the reference number.","page":53,"deck":"s01"},{"id":"s01c44","front":"Volunteer ambulance: when can care NOT be transferred?","back":"After lifesaving interventions: intubation, whole blood, CPR, defibrillation, cardioversion, cardiac meds.","page":54,"deck":"s01"},{"id":"s01c45","front":"Event medicine: who directs care?","back":"FLFR paramedics under protocol. Other medical professionals can advise but not direct.","page":55,"deck":"s01"},{"id":"s01c46","front":"Event medicine: allergic reaction needing epi or Solu-Medrol?","back":"Must be transported.","page":56,"deck":"s01"},{"id":"s01c47","front":"Firefighter rehab triggers?","back":"Over 30 min heavy exertion, 2+ SCBA cylinders, heat index over 90°F, signs of distress, or Command's call.","page":57,"deck":"s01"},{"id":"s01c48","front":"Rehab rest and vitals interval?","back":"At least 10–20 minutes rest; vitals every 10 minutes.","page":58,"deck":"s01"},{"id":"s01c49","front":"Return-to-work criteria (NFPA 1584)?","back":"HR under 100, SBP under 160, DBP under 100, temp under 100.4°F, A&Ox4. All required.","page":59,"deck":"s01"},{"id":"s01c50","front":"Firefighters who must be transported from rehab?","back":"Chest pain or arrhythmia, vitals not resolving after 2 rest cycles, heat stroke (AMS, temp over 104°F), any injury.","page":59,"deck":"s01"},{"id":"s01c51","front":"Rehab case review deadline?","back":"Reviewed with the Medical Director within one month.","page":59,"deck":"s01"},{"id":"s02c01","front":"Abdominal pain: two tests to rule out mimics?","back":"12-lead (ischemia can present as epigastric pain) and BGL (hypoglycemia).","page":64,"deck":"s02"},{"id":"s02c02","front":"GI bleed: three things to avoid?","back":"NSAIDs/aspirin, an NG tube, anything by mouth.","page":64,"deck":"s02"},{"id":"s02c03","front":"Suspected AAA?","back":"Severe back/abdominal pain, hypotension, pulsatile mass: don't palpate repeatedly or delay transport.","page":64,"deck":"s02"},{"id":"s02c04","front":"Adult mild allergic reaction?","back":"Benadryl 50 mg IV/IO/IM (over 2 min IV).","page":65,"deck":"s02"},{"id":"s02c05","front":"Adult moderate/severe anaphylaxis?","back":"Epi 1:1,000 0.5 mg IM lateral thigh q3 min prn, albuterol, Benadryl 50 mg, Solu-Medrol 125 mg.","page":65,"deck":"s02"},{"id":"s02c06","front":"Anaphylactic shock definition (adult)?","back":"Allergic signs plus loss of radial pulse and/or SBP under 100, AMS, shock.","page":65,"deck":"s02"},{"id":"s02c07","front":"Adult anaphylactic shock treatment?","back":"Epi 0.5 mg IM, then immediately push-dose epi (IO recommended), 1 L NS, plus Benadryl, Solu-Medrol, albuterol.","page":65,"deck":"s02"},{"id":"s02c08","front":"Pediatric anaphylaxis epi?","back":"1:1,000 0.01 mg/kg IM, max single 0.5 mg, q3 min prn.","page":66,"deck":"s02"},{"id":"s02c09","front":"Pediatric Benadryl max?","back":"1 mg/kg, max total 50 mg.","page":66,"deck":"s02"},{"id":"s02c10","front":"AEIOU-TIPS?","back":"Alcohol, Epilepsy, Insulin, Overdose, Uremia, Trauma, Infection, Psychiatric, Stroke.","page":67,"deck":"s02"},{"id":"s02c11","front":"Hyperactive delirium (adult) treatment beyond chemical restraint?","back":"Sodium bicarb 50 mEq in 100 ml, 1 L NS, rapid cooling if temp over 104°.","page":69,"deck":"s02"},{"id":"s02c12","front":"Who goes to the ED regardless of post-treatment glucose?","back":"Patients on oral hypoglycemics: glyburide, glimepiride, glipizide.","page":70,"deck":"s02"},{"id":"s02c13","front":"Adult hypoglycemia treatment?","back":"BGL under 60: oral glucose 15 g if able, or D10 100 ml and recheck, repeat prn. No access: glucagon 1 mg IM.","page":70,"deck":"s02"},{"id":"s02c14","front":"DKA signs and fluid?","back":"N/V, abdominal pain, Kussmaul breathing, AMS, fruity breath; BGL over 300 with DKA signs: 1 L NS.","page":70,"deck":"s02"},{"id":"s02c15","front":"Pediatric hypoglycemia?","back":"D10 5 ml/kg (max 100 ml), may repeat 1x. Glucagon 0.5 mg (under 20 kg) or 1 mg IM. No oral glucose under 2.","page":71,"deck":"s02"},{"id":"s02c16","front":"Dystonic reaction causes and treatment?","back":"Antipsychotics, antiemetics, antidepressants. Benadryl 50 mg adult; 1 mg/kg peds (max 50).","page":72,"deck":"s02"},{"id":"s02c17","front":"Who needs extra caution with fluid boluses?","back":"CHF and renal failure/dialysis patients. Consider sepsis in all dehydrated patients.","page":73,"deck":"s02"},{"id":"s02c18","front":"Hyperkalemia: earliest ECG sign and late signs?","back":"Peaked T waves. Later: sine wave, wide QRS, VT under 120, severe brady, high-degree blocks.","page":74,"deck":"s02"},{"id":"s02c19","front":"Hyperkalemia bundle and order?","back":"Calcium chloride 1 g over 2 min FIRST, albuterol 10 mg neb, sodium bicarb 50 mEq over 2 min. Give all.","page":74,"deck":"s02"},{"id":"s02c20","front":"Hyperkalemia line caution?","back":"Flush between calcium chloride and sodium bicarb.","page":74,"deck":"s02"},{"id":"s02c21","front":"Adult seizure meds?","back":"Versed 5 mg IV/IO/IN/IM, repeat 1x. Still seizing after 2 doses: ketamine 100 mg (another 100 if intubating).","page":76,"deck":"s02"},{"id":"s02c22","front":"Pediatric seizure Versed?","back":"0.1 mg/kg IV/IO or 0.2 mg/kg IN/IM, repeat 1x; then ketamine 1 mg/kg.","page":76,"deck":"s02"},{"id":"s02c23","front":"Febrile child cooling: do's and don'ts?","back":"Remove clothes and fan. No wet sheets, no ice packs, no shivering. Tylenol 15 mg/kg if not seizing and can take PO.","page":76,"deck":"s02"},{"id":"s02c24","front":"Sepsis fever definition?","back":"Temp over 100.4 or under 96.8.","page":77,"deck":"s02"},{"id":"s02c25","front":"Sepsis Alert (qSOFA) criteria?","back":"Suspected infection plus 2 of 3: SBP under 100 or MAP under 65, AMS, RR over 22 and/or EtCO2 under 25.","page":77,"deck":"s02"},{"id":"s02c26","front":"Adult qSOFA-positive treatment?","back":"Sepsis Alert, scene under 10 min, 1 L NS regardless of BP, cefepime 2 g, push-dose epi if fluids fail.","page":78,"deck":"s02"},{"id":"s02c27","front":"Sickle cell crisis treatment?","back":"500 ml NS (may repeat), pain management, Zofran 4 mg. Peds 20 ml/kg.","page":79,"deck":"s02"},{"id":"s02c28","front":"Stroke: what to check before calling the alert?","back":"BGL. Under 60: treat as hypoglycemia.","page":80,"deck":"s02"},{"id":"s02c29","front":"BE-FAST?","back":"Balance, Eyes, Face droop, Arm drift/AMS, Slurred speech, Time onset under 24 hours.","page":80,"deck":"s02"},{"id":"s02c30","front":"RACE: what does it measure and max score?","back":"Large-vessel occlusion likelihood. Facial palsy, arm, leg, gaze, aphasia or neglect. Max 9.","page":80,"deck":"s02"},{"id":"s02c31","front":"RACE: aphasia vs neglect?","back":"Test aphasia for right-sided deficits; neglect (agnosia) for left-sided deficits.","page":80,"deck":"s02"},{"id":"s02c32","front":"Stroke positioning, O2 and IV?","back":"Head up 30° (unless supine helps), 2 L NC for SpO2 under 95%, 18g in the AC.","page":81,"deck":"s02"},{"id":"s02c33","front":"Stroke onset time definition?","back":"Last known well. Woke up with symptoms or unknown: Stroke Alert to a Stroke Center.","page":81,"deck":"s02"},{"id":"s02c34","front":"Stroke report to the hospital?","back":"LKW, RACE and deficits, anticoagulants, BP, BGL, ETA.","page":81,"deck":"s02"},{"id":"s02c35","front":"Pediatric stroke destination?","back":"Pediatric comprehensive ED/comprehensive stroke center: BHMC or JDCH.","page":82,"deck":"s02"},{"id":"s03c01","front":"What is auto-PEEP and who is at risk?","back":"Breaths delivered before full exhalation trap air (COPD/asthma). Risks: pneumothorax and hypotension.","page":85,"deck":"s03"},{"id":"s03c02","front":"Auto-PEEP fix: how long do you stop ventilating?","back":"Disconnect/stop positive pressure 20–40 seconds (10–20 for peds) to let them fully exhale.","page":85,"deck":"s03"},{"id":"s03c03","front":"SpO2 targets in respiratory distress?","back":"95%, or 90% for COPD and asthma. Ignore EtCO2 targets in COPD/asthma.","page":85,"deck":"s03"},{"id":"s03c04","front":"Adult: when to assist ventilations with BVM?","back":"RR under 10 or over 29 with shallow breathing. Advanced airway if BVM over 2 min and unconscious with no gag.","page":85,"deck":"s03"},{"id":"s03c05","front":"CPAP setting and contraindications?","back":"10 cm H2O. Contraindicated: no spontaneous breathing, decreased LOC. Relative: SBP under 90.","page":85,"deck":"s03"},{"id":"s03c06","front":"Adult COPD bronchospasm treatment?","back":"Albuterol 2.5 mg neb prn, CPAP 10 (Versed 2 mg if not tolerating), Solu-Medrol 125 mg IV/IM once.","page":86,"deck":"s03"},{"id":"s03c07","front":"Adult asthma 1st bundle?","back":"Albuterol 2.5 mg neb prn and Solu-Medrol 125 mg IV/IM once.","page":86,"deck":"s03"},{"id":"s03c08","front":"Adult severe asthma 2nd bundle?","back":"CPAP (Versed 2 mg prn), albuterol, epi 1:1,000 0.5 mg IM every 5 min x2 more, mag infusion, Solu-Medrol 125 mg.","page":86,"deck":"s03"},{"id":"s03c09","front":"Asthmatic worsens on CPAP?","back":"Remove the CPAP immediately.","page":86,"deck":"s03"},{"id":"s03c10","front":"Intubated asthma patient with bronchospasm?","back":"In-line nebulized albuterol.","page":86,"deck":"s03"},{"id":"s03c11","front":"Pediatric asthma: Solu-Medrol and EtCO2 target?","back":"Solu-Medrol 2 mg/kg over 2 min. EtCO2 35–45.","page":87,"deck":"s03"},{"id":"s03c12","front":"Pediatric severe asthma: epi dose and CPAP age?","back":"Epi 1:1,000 0.01 mg/kg IM, max 0.3 mg, repeat 2x q5 min. CPAP only over age 6.","page":87,"deck":"s03"},{"id":"s03c13","front":"Croup/epiglottitis epi dose?","back":"Epi 1:1,000 3 ml (3 mg) by nebulizer.","page":87,"deck":"s03"},{"id":"s03c14","front":"Croup/epiglottitis: what NOT to do?","back":"Don't stress the child. No intubation, OPA or NPA; BVM if needed. Go to the closest approved pediatric ED.","page":87,"deck":"s03"},{"id":"s03c15","front":"Croup vs epiglottitis: age and onset?","back":"Croup: usually under 3, sick a couple of days, low fever. Epiglottitis: 3–6, sudden onset, high fever, tripod, drooling.","page":87,"deck":"s03"},{"id":"s03c16","front":"Who is responsible once paralytics are given?","back":"The designated EMS Officer: ensures the airway and rides to the ED (except air rescue).","page":88,"deck":"s03"},{"id":"s03c17","front":"Two airway rules for every intubation?","back":"High-flow O2 by nasal cannula before and during; video laryngoscopy first if available.","page":88,"deck":"s03"},{"id":"s03c18","front":"Adult induction doses?","back":"Etomidate 0.3 mg/kg, max 30 mg, OR ketamine 2 mg/kg diluted, max 200 mg. Rapid push, may repeat 1x.","page":88,"deck":"s03"},{"id":"s03c19","front":"Adult rocuronium dose?","back":"1 mg/kg: min 50 mg, max 100 mg IV/IO.","page":88,"deck":"s03"},{"id":"s03c20","front":"Adult post-intubation sedation and pain?","back":"Ketamine 100–200 mg (after etomidate induction); fentanyl 100 mcg slow, repeat once in 20 min (200 mcg total).","page":88,"deck":"s03"},{"id":"s03c21","front":"Failed airway sequence?","back":"Exhaust BVM and SGA first; then surgical airway: cric for adults, needle cric for age 10 and under.","page":88,"deck":"s03"},{"id":"s03c22","front":"Pediatric induction and paralytic?","back":"Etomidate 0.3 mg/kg (max 30) or ketamine 1 mg/kg; rocuronium 1 mg/kg. Never roc without induction.","page":89,"deck":"s03"},{"id":"s03c23","front":"Pediatric post-intubation fentanyl?","back":"1 mcg/kg slow over 2 min, q5 min prn. Max single 100 mcg, total 200 mcg.","page":89,"deck":"s03"},{"id":"s03c24","front":"Example indications for paralytics?","back":"Status epilepticus, multi-system trauma, GCS 8 or less, trismus, airway burns, traumatic shock, respiratory failure.","page":90,"deck":"s03"},{"id":"s03c25","front":"DSI: sequence and preferred induction agent?","back":"Induction, then about 3 minutes of oxygenation/stabilization, then paralytic. Ketamine is first-line.","page":90,"deck":"s03"},{"id":"s03c26","front":"RSI vs DSI: ideal patient?","back":"RSI: cooperative (TBI, arrest, airway burn). DSI: uncooperative, hypoxic, unstable (trauma, pneumonia, COPD).","page":90,"deck":"s03"},{"id":"s03c27","front":"Ventilator contraindications?","back":"Can't constantly monitor the patient, or weight under 6 kg.","page":91,"deck":"s03"},{"id":"s03c28","front":"Ventilator in cardiac arrest: mode and settings?","back":"CPR mode/PCV+: RR 10, PS 15, PEEP 5, FiO2 100%. Low volume alarm: Pcontrol 20 (ETT) or 25 (SGA).","page":91,"deck":"s03"},{"id":"s03c29","front":"Ventilator post-ROSC settings?","back":"PCV+: RR 12, PS 15, PEEP 5, FiO2 100%. Desynchrony: switch to ASV.","page":91,"deck":"s03"},{"id":"s03c30","front":"Respiratory failure on the vent: mode and MV adjustments?","back":"ASV, 100% MinVol, PEEP 5. EtCO2 high: raise MV 20% steps (max 150%). Apneic and EtCO2 low: lower 10% (to 90%).","page":91,"deck":"s03"},{"id":"s03c31","front":"NIV settings: obstructive vs restrictive disease?","back":"Obstructive: PS 8, PEEP 6 (max PS 14, PEEP 6). Restrictive: PS 5, PEEP 5 (max PS 10, PEEP 10).","page":92,"deck":"s03"},{"id":"s03c32","front":"NIV: titration steps and pressure limit?","back":"Raise PS or PEEP in 2 cm steps; peak pressure no more than 25 unless an NG tube is in.","page":92,"deck":"s03"},{"id":"s04c01","front":"Chest pain/STEMI: which two meds are never given for suspected cardiac chest pain?","back":"Ketamine and Toradol.","page":95,"deck":"s04"},{"id":"s04c02","front":"STEMI: where should the IV go and why?","back":"Avoid the right hand/wrist (cath access). Use the right AC or any site on the left arm.","page":95,"deck":"s04"},{"id":"s04c03","front":"Aspirin dose for chest pain and when to withhold it?","back":"324 mg (four 81 mg) chewed. Withhold if they took 324 mg in the last 24 h; if less, give the full 324 mg.","page":95,"deck":"s04"},{"id":"s04c04","front":"Fentanyl for cardiac chest pain?","back":"50 mcg slow IV/IO/IM or 100 mcg IN, repeat every 5 min prn, max 200 mcg.","page":95,"deck":"s04"},{"id":"s04c05","front":"Who gets aspirin only (no fentanyl) in chest pain?","back":"Patients with ST elevation but no pain. Fentanyl is only for ischemic pain.","page":95,"deck":"s04"},{"id":"s04c06","front":"NTG in STEMI?","back":"Do not give NTG in STEMI, unless CHF is associated: then NTG paste is OK.","page":96,"deck":"s04"},{"id":"s04c07","front":"STEMI criteria: convex or straight ST morphology?","back":"Elevation in 2+ contiguous leads: 2 mm+ in V2–V3, or 1 mm+ in all other leads.","page":96,"deck":"s04"},{"id":"s04c08","front":"STEMI criteria: concave (smiley) morphology?","back":"2 mm or greater in 2+ contiguous leads, in any lead.","page":96,"deck":"s04"},{"id":"s04c09","front":"15-lead: where do V4, V5, V6 move?","back":"Per the protocol: V4 moves right and is labeled V7; V5 and V6 move posterior and become V8 and V9. Print both ECGs.","page":97,"deck":"s04"},{"id":"s04c10","front":"STEMI disqualifiers (mimics)?","back":"QRS over 0.12 (LBBB, paced), LVH, pericarditis, early repolarization, under 2 mm concave elevation.","page":97,"deck":"s04"},{"id":"s04c11","front":"Ischemia that doesn't meet STEMI criteria: destination?","back":"Still a STEMI facility, as a CARDIAC ALERT.","page":97,"deck":"s04"},{"id":"s04c12","front":"LVH voltage rule?","back":"Largest S in V1/V2 + largest R in V5/V6. Over 35 small boxes = high suspicion of LVH.","page":97,"deck":"s04"},{"id":"s04c13","front":"CHF treatment list?","back":"12-lead, CPAP 10 cmH2O, Lasix 40 mg IV once, aspirin 324 mg, NTG paste 1 inch to the upper chest.","page":98,"deck":"s04"},{"id":"s04c14","front":"CPAP contraindications in CHF?","back":"SBP under 90, AMS (lethargic), apnea.","page":98,"deck":"s04"},{"id":"s04c15","front":"CHF: when do you withhold nitrates?","back":"Febrile (over 100.4 or under 96.8) or nursing-home patient with suspected pneumonia.","page":98,"deck":"s04"},{"id":"s04c16","front":"Cardiogenic shock: hypotension treatment and target?","back":"Push-dose epi until SBP is 100+, then treat CHF/chest pain.","page":99,"deck":"s04"},{"id":"s04c17","front":"LVAD patient with toe pain: destination?","back":"An LVAD center, regardless of complaint.","page":100,"deck":"s04"},{"id":"s04c18","front":"LVAD: fluid limit, CPR method, and which monitor value to trust?","back":"No more than a 500 ml bolus. Manual compressions only, never mechanical. Use EtCO2 (SpO2 unreliable).","page":100,"deck":"s04"},{"id":"s04c19","front":"LVAD: when are chest compressions done?","back":"Only if there's no hand pump, the pump isn't working, nothing else restarts it, and the patient is in arrest.","page":101,"deck":"s04"},{"id":"s04c20","front":"LVAD: normal MAP range and how to check pump function?","back":"MAP/SBP 60–100 by Doppler. Listen for a continuous hum over chest and upper abdomen.","page":101,"deck":"s04"},{"id":"s04c21","front":"Broward VAD centers?","back":"Cleveland Clinic and Memorial Regional (adult and pediatric).","page":101,"deck":"s04"},{"id":"s04c22","front":"Adult unstable bradycardia definition and treatments?","back":"SBP under 100, AMS, shock. 12-lead, 1 L NS, atropine 1 mg (q3–5 min, max 3 mg), push-dose epi, pacing.","page":102,"deck":"s04"},{"id":"s04c23","front":"Adult pacing: starting rate and when to skip straight to it?","back":"Start at 60. Go straight to pacing for chest pain or high-degree AV block with hypotension, or no IV.","page":102,"deck":"s04"},{"id":"s04c24","front":"Pacing sedation adult vs pediatric?","back":"Adult etomidate 10 mg slow, may repeat 1x. Peds 0.15 mg/kg, max 20 mg single dose, repeat 1x in 3 min.","page":102,"deck":"s04"},{"id":"s04c25","front":"Pediatric bradycardia: most likely cause and first treatment?","back":"Hypoxia. Oxygenate and ventilate first.","page":103,"deck":"s04"},{"id":"s04c26","front":"Pediatric pacing start rate?","back":"80 BPM.","page":103,"deck":"s04"},{"id":"s04c27","front":"Rapid A-fib/flutter definition?","back":"Ventricular rate over 120.","page":104,"deck":"s04"},{"id":"s04c28","front":"Cardizem for rapid A-fib with SBP over 90?","back":"10 mg IV/IO over 2 min; if HR still over 120 after 5 min, 15 mg over 2 min.","page":104,"deck":"s04"},{"id":"s04c29","front":"Rapid A-fib with SBP under 90?","back":"1 L NS, calcium chloride 1 g slow; if SBP over 80, Cardizem 10 mg; if SBP under 70 or no improvement, call the Medical Director.","page":104,"deck":"s04"},{"id":"s04c30","front":"Can you cardiovert A-fib/A-flutter?","back":"No. High risk of embolic stroke.","page":104,"deck":"s04"},{"id":"s04c31","front":"SVT definition (adult, child, infant)?","back":"Adult: regular narrow-complex 150+ with no P/flutter waves. Child over 180. Infant over 220.","page":105,"deck":"s04"},{"id":"s04c32","front":"Adult stable SVT treatment?","back":"Vagal maneuvers (modified Valsalva), then adenosine 12 mg rapid with 10 ml flush OR Cardizem 10 mg then 15 mg.","page":105,"deck":"s04"},{"id":"s04c33","front":"Adult synchronized cardioversion energy?","back":"Zoll 150 J then 200 J. LifePak 300 J then 360 J.","page":105,"deck":"s04"},{"id":"s04c34","front":"Modified Valsalva (REVERT) steps?","back":"Blow into a 10 cc syringe 15 sec sitting up; then lay flat and raise legs to 45° for 15 sec; then sit up and monitor 30 sec.","page":106,"deck":"s04"},{"id":"s04c35","front":"Pediatric adenosine doses?","back":"0.1 mg/kg rapid (max 6 mg), then 0.2 mg/kg (max 12 mg) if no change in 1 min.","page":107,"deck":"s04"},{"id":"s04c36","front":"Pediatric vagal maneuver for young children?","back":"Bag of ice water over the face covering nose and mouth for 15 seconds.","page":107,"deck":"s04"},{"id":"s04c37","front":"Pediatric synchronized cardioversion?","back":"1 J/kg, then 2 J/kg, then 4 J/kg.","page":107,"deck":"s04"},{"id":"s04c38","front":"WPW: ECG signs and drugs to avoid?","back":"Short PR, wide QRS, delta wave. No adenosine or Cardizem.","page":108,"deck":"s04"},{"id":"s04c39","front":"Really wide complex tachycardia: what is it likely and what's the treatment?","back":"QRS over 200 ms, rate about 100–120: likely hyperkalemia. NO amiodarone. Calcium chloride 1 g and sodium bicarb 50 mEq over 2 min.","page":109,"deck":"s04"},{"id":"s04c40","front":"WCT definition?","back":"QRS 0.12 or more (0.09 peds), rate over 120, no discernible P waves.","page":110,"deck":"s04"},{"id":"s04c41","front":"ECG features favoring VT?","back":"Precordial concordance, capture/fusion beats, no RS in precordial leads, R-to-S over 100 ms.","page":110,"deck":"s04"},{"id":"s04c42","front":"Rule for regular WCTs?","back":"Treat all regular WCTs as VT unless proven supraventricular.","page":110,"deck":"s04"},{"id":"s04c43","front":"Why not cardiovert an irregularly irregular WCT?","back":"Likely A-fib with aberrancy: embolic stroke risk.","page":110,"deck":"s04"},{"id":"s04c44","front":"Adult stable VT treatment?","back":"Amio 150 mg in 100 ml over 10 min (may repeat 1x; give all of it even if VT stops). Pregnancy or no amio: lidocaine 100 mg.","page":111,"deck":"s04"},{"id":"s04c45","front":"After 2 cardioversions or 2+ ICD shocks: what's given?","back":"Amio infusion 150 mg in 100 ml over 10 min, if not already given.","page":111,"deck":"s04"},{"id":"s04c46","front":"Stable torsades (adult)?","back":"Mag sulfate 2 g in 100 ml, 10-drop set wide open.","page":113,"deck":"s04"},{"id":"s04c47","front":"Unstable torsades defibrillation energy?","back":"Zoll 200 J; LifePak 300 J then 360 J. Then mag 2 g.","page":113,"deck":"s04"},{"id":"s04c48","front":"Pediatric torsades?","back":"Mag 40 mg/kg in 100 ml wide open; if unstable, defibrillate 2, 4, then 10 J/kg.","page":114,"deck":"s04"},{"id":"s05c01","front":"Do-not-resuscitate decision: what rhythm and breathing status must the patient have?","back":"Asystole and apneic.","page":117,"deck":"s05"},{"id":"s05c02","front":"Name the conclusive signs (only ONE needed) for not starting resuscitation.","back":"Lividity, rigor mortis, tissue decomposition, a valid DNR (yellow paper), or injury incompatible with life.","page":117,"deck":"s05"},{"id":"s05c03","front":"Name the presumptive signs (ALL needed) for not starting resuscitation.","back":"Known downtime over 20 min with no CPR, asystole, pupils fixed and dilated, apneic, and no hypothermia.","page":117,"deck":"s05"},{"id":"s05c04","front":"Adult medical termination of resuscitation: who makes the call (FLFR)?","back":"A Battalion Chief, when all criteria are met.","page":117,"deck":"s05"},{"id":"s05c05","front":"Termination of resuscitation: minimum total resuscitation time and EtCO2?","back":"At least 20 minutes (asystole or PEA rate under 20) and EtCO2 under 10 mmHg.","page":117,"deck":"s05"},{"id":"s05c06","front":"Termination of resuscitation: temperature requirement?","back":"Temperature above 90°F.","page":117,"deck":"s05"},{"id":"s05c07","front":"Two situations where you never terminate on scene?","back":"A shockable rhythm at any time, and any witnessed cardiac arrest (must be transported).","page":117,"deck":"s05"},{"id":"s05c08","front":"Termination of resuscitation: age limit?","back":"Not a pediatric patient (over 18).","page":117,"deck":"s05"},{"id":"s05c09","front":"Adult cardiac arrest transport destination?","back":"The closest approved STEMI Center.","page":118,"deck":"s05"},{"id":"s05c10","front":"Pediatric cardiac or respiratory arrest transport destination?","back":"A comprehensive pediatric emergency department, regardless of ROSC.","page":118,"deck":"s05"},{"id":"s05c11","front":"MICCR: epinephrine and first defibrillation time targets?","back":"Epi within 3 minutes of patient contact; pads on and defibrillate within 3 minutes for shockable rhythms.","page":118,"deck":"s05"},{"id":"s05c12","front":"Minimum time to remain on scene working a (non-traumatic) code?","back":"20 minutes.","page":118,"deck":"s05"},{"id":"s05c13","front":"High-performance CPR: compressions per cycle?","back":"220 compressions in two minutes.","page":118,"deck":"s05"},{"id":"s05c14","front":"Maximum pause for rhythm check and defibrillation?","back":"Under 5 seconds. A 10-second pause equals about a 40-second loss of brain perfusion.","page":118,"deck":"s05"},{"id":"s05c15","front":"Ventilation rate with an SGA during CPR?","back":"1 breath every 6 seconds, asynchronous with compressions.","page":118,"deck":"s05"},{"id":"s05c16","front":"When is the mechanical CPR device applied?","back":"After a minimum of 3 rounds of 220 compressions (about 6 minutes), once more crew arrive.","page":118,"deck":"s05"},{"id":"s05c17","front":"What do you do if EtCO2 drops significantly after mechanical CPR starts?","back":"Discontinue the device and resume manual compressions.","page":118,"deck":"s05"},{"id":"s05c18","front":"Adult epi drip mix and rate?","back":"2 mg epi in a 100 ml NS bag, 10-drop set, 1 drop per second (runs about 16 minutes). Never more than 2 mg in any bag.","page":118,"deck":"s05"},{"id":"s05c19","front":"VF arrest amiodarone doses?","back":"1st dose 300 mg IV/IO push, 2nd dose 150 mg IV/IO push.","page":118,"deck":"s05"},{"id":"s05c20","front":"When is the antiarrhythmic given in VF?","back":"If the patient does not convert after ONE defibrillation.","page":118,"deck":"s05"},{"id":"s05c21","front":"Lidocaine dose when amiodarone is not available?","back":"1 mg/kg IV/IO push, max 100 mg. Repeat once after 5 minutes if no effect.","page":118,"deck":"s05"},{"id":"s05c22","front":"Torsades in cardiac arrest (adult)?","back":"Defibrillate, then magnesium 2 g IV/IO slow push.","page":118,"deck":"s05"},{"id":"s05c23","front":"EtCO2 targets during resuscitation?","back":"Under 10 mmHg: improve compressions. Above 20 mmHg is ideal.","page":119,"deck":"s05"},{"id":"s05c24","front":"Name the H's and their treatments.","back":"Hydrogen ion: ventilate. Hyperkalemia: protocol. Hypoglycemia: D10 250 ml. Hypoxia: O2 and ventilate. Hypovolemia: 500 ml bolus. Hypothermia: warm.","page":119,"deck":"s05"},{"id":"s05c25","front":"Toxins in arrest: match the antidote (opiates, beta blockers, TCAs, calcium channel blockers).","back":"Opiates: Narcan. Beta blockers: glucagon. TCAs: sodium bicarb. CCBs: calcium chloride.","page":119,"deck":"s05"},{"id":"s05c26","front":"Adult defibrillation energy by monitor?","back":"200 J on the Zoll, 360 J on the LifePak.","page":120,"deck":"s05"},{"id":"s05c27","front":"Pediatric defibrillation energy sequence?","back":"2 J/kg, then 4 J/kg, then 10 J/kg or max on all after.","page":121,"deck":"s05"},{"id":"s05c28","front":"Pediatric amiodarone in arrest?","back":"5 mg/kg every 5 minutes, max single dose 300 mg, may repeat once.","page":121,"deck":"s05"},{"id":"s05c29","front":"Pediatric torsades in arrest?","back":"Mag sulfate 40 mg/kg IV/IO slow push, then defibrillate.","page":121,"deck":"s05"},{"id":"s05c30","front":"Pediatric epi drip in arrest?","back":"Weight-based bolus, then a drip of (weight-based dose × 2) in a 100 ml bag over 16 minutes, using 1:10,000.","page":121,"deck":"s05"},{"id":"s05c31","front":"Refractory VF/VT definition?","back":"Persistent VF/VT not converted by standard defibrillation (3 shocks).","page":122,"deck":"s05"},{"id":"s05c32","front":"Refractory VF: next steps after 3 shocks and 450 mg amiodarone?","back":"Change pad placement and/or double sequential defibrillation (Zoll only).","page":122,"deck":"s05"},{"id":"s05c33","front":"ECMO alert indications?","back":"Under 65, witnessed, CPR within 5 min, shockable rhythm, and under 20 miles / under 30 min transport.","page":122,"deck":"s05"},{"id":"s05c34","front":"ECMO alert exclusions?","back":"Initial asystole, unknown downtime, poor baseline neuro function or DNR, sustained ROSC after 20 min, or over 20 miles / 30 min.","page":122,"deck":"s05"},{"id":"s05c35","front":"Where do refractory VF ECMO alerts go?","back":"Memorial Regional, the only Broward hospital that can take them. Call 954-265-2633.","page":122,"deck":"s05"},{"id":"s05c36","front":"Hyperkalemia in arrest (adult): drugs and doses?","back":"Calcium chloride 1 g slow over 2 min; once intubated, albuterol 10 mg neb; sodium bicarb 50 mEq slow over 2 min.","page":124,"deck":"s05"},{"id":"s05c37","front":"CPR-induced consciousness treatment?","back":"Etomidate 10 mg slow push IV/IO, may repeat once prn.","page":124,"deck":"s05"},{"id":"s05c38","front":"Third-trimester arrest positioning?","back":"Manually displace the uterus to the left instead of tilting the patient.","page":124,"deck":"s05"},{"id":"s05c39","front":"Adult post-ROSC order of management?","back":"Rate, rhythm, blood pressure (SBP goal 100), then 12-lead. 1 L NS if hypotensive.","page":125,"deck":"s05"},{"id":"s05c40","front":"Post-ROSC hypotension (adult): epi drip change and MAP goal?","back":"Slow the drip to 1 drop every 4 seconds (30 mcg/min), or push-dose epi plus fluid. Ideal MAP 65–70.","page":125,"deck":"s05"},{"id":"s05c41","front":"Post-VF ROSC: when is an amiodarone infusion given?","back":"150 mg in 100 ml over 10 min if they converted after an amio bolus plus defibrillation. None if they converted on the first shock.","page":125,"deck":"s05"},{"id":"s05c42","front":"Minimum pediatric SBP values?","back":"Neonate 60, infant 70, age 1–10: 70 + (2 × age), over 10: 90 mmHg.","page":126,"deck":"s05"},{"id":"s05c43","front":"Pediatric fluid boluses post-ROSC?","back":"20 ml/kg, repeat up to 2 more times, max 60 ml/kg (non-trauma).","page":126,"deck":"s05"},{"id":"s05c44","front":"Pediatric bradycardia post-ROSC: when to start CPR?","back":"HR under 60 with poor perfusion after 60 seconds of oxygenation/ventilation (30 seconds for a neonate).","page":126,"deck":"s05"},{"id":"s05c45","front":"Pit Crew 2-person roles?","back":"Position 1: code management, BVM, i-gel, EtCO2, suction. Position 2: monitor, continuous CPR, defibrillate after 2 min.","page":128,"deck":"s05"},{"id":"s05c46","front":"Pit Crew 3-person: who gives the first 1:10,000 epi bolus?","back":"Position 3 (also does CPR and establishes the IO).","page":129,"deck":"s05"},{"id":"s06c01","front":"Level One trauma: target on-scene time?","back":"10 minutes or less; longer must be explained in the ePCR.","page":133,"deck":"s06"},{"id":"s06c02","front":"Trauma fluids: when do you give them (permissive hypotension)?","back":"Withhold unless mental status worsens and SBP falls under 80.","page":133,"deck":"s06"},{"id":"s06c03","front":"Minimum paramedics in the back for a Level One trauma?","back":"Two, if it doesn't significantly delay transport.","page":133,"deck":"s06"},{"id":"s06c04","front":"What may interrupt the treating paramedic's primary survey?","back":"Only an unsafe scene or airway obstruction. Delegate bleeding, dyspnea, respiratory arrest.","page":133,"deck":"s06"},{"id":"s06c05","front":"MCI levels by patient count?","back":"I: 5–10, II: 11–20, III: 21–100, IV: 101–1000, V: over 1000.","page":133,"deck":"s06"},{"id":"s06c06","front":"START: time per victim and mnemonic?","back":"60 seconds or less. RPM: Respirations, Perfusion, Mental status.","page":134,"deck":"s06"},{"id":"s06c07","front":"Triage ribbon colors?","back":"Red immediate, yellow delayed, green minor, black deceased, blue HazMat exposure.","page":134,"deck":"s06"},{"id":"s06c08","front":"Triage rule for borderline decisions?","back":"Always tag to the more urgent priority. The first finding that produces RED stops the assessment.","page":134,"deck":"s06"},{"id":"s06c09","front":"START respirations step?","back":"Over 30: RED. 30 or less: check perfusion. Not breathing after opening airway: BLACK.","page":136,"deck":"s06"},{"id":"s06c10","front":"START perfusion and mental status?","back":"No radial pulse or cap refill over 2 sec: RED. Can't follow commands: RED. Otherwise GREEN (or YELLOW for injuries).","page":136,"deck":"s06"},{"id":"s06c11","front":"JumpSTART: age range and respiratory cut-offs?","back":"Ages 1–8. RR under 15 or over 45: RED. Apneic: open airway, 5 rescue breaths; still apneic: BLACK.","page":137,"deck":"s06"},{"id":"s06c12","front":"JumpSTART mental status?","back":"Inappropriate response to pain, posturing, or unresponsive: RED. Normal: YELLOW.","page":137,"deck":"s06"},{"id":"s06c13","front":"Pediatric trauma: age cut-off and destination?","back":"15 or younger. Pediatric trauma alerts go to the nearest appropriate Pediatric Trauma Center.","page":143,"deck":"s06"},{"id":"s06c14","front":"Pediatric RED criterion for circulation?","back":"Faint or non-palpable carotid/femoral pulse, or SBP under 50.","page":143,"deck":"s06"},{"id":"s06c15","front":"Pediatric RED criteria for burns and amputation?","back":"2nd/3rd-degree burns 10%+ BSA, any high-voltage/lightning burn, amputation proximal to wrist/ankle.","page":143,"deck":"s06"},{"id":"s06c16","front":"Pediatric BLUE criteria: how many needed and what are they?","back":"Any two: amnesia/LOC; radial/pedal pulse absent or SBP under 100; single closed long-bone fracture; 11 kg or less (33 inches or less).","page":144,"deck":"s06"},{"id":"s06c17","front":"High-index (Level II) trauma: fall heights?","back":"Over 12 feet adult; over 6 feet pediatric. Any height if over 55 on anticoagulants/antiplatelets.","page":145,"deck":"s06"},{"id":"s06c18","front":"High-index trauma: vehicle criteria?","back":"Extrication over 15 min, rollover, death in same compartment, major intrusion. Also separation from a bicycle.","page":145,"deck":"s06"},{"id":"s06c19","front":"Antiplatelets vs anticoagulants listed?","back":"Antiplatelets: Plavix, Brilinta, Effient. Anticoagulants: Coumadin, Pradaxa, Xarelto, Eliquis, Lovenox.","page":145,"deck":"s06"},{"id":"s06c20","front":"Level II consideration criteria (name 4)?","back":"Age 65+ with minimal symptoms or SBP under 110, MVC over 20 mph with seatbelt marks, partial ejection, dialysis, OB over 20 weeks.","page":146,"deck":"s06"},{"id":"s06c21","front":"Burn first steps?","back":"Irrigate with room-temp water or NS 1–2 min. No ice. Don't remove adhered tar/clothing. Remove jewelry.","page":147,"deck":"s06"},{"id":"s06c22","front":"Airway burn signs that call for early intubation?","back":"Hoarse voice, singed nasal hair, carbonaceous sputum, stridor, facial burns.","page":147,"deck":"s06"},{"id":"s06c23","front":"Adult burn fluid threshold and dose?","back":"2nd-degree over 15% or 3rd-degree over 5%: burn sheet and 1 L NS.","page":147,"deck":"s06"},{"id":"s06c24","front":"Palmar method?","back":"The patient's hand with fingers is about 1% BSA.","page":147,"deck":"s06"},{"id":"s06c25","front":"Pediatric burns: ETT size tip and fluid dose?","back":"Use an ETT 0.5–1.0 mm smaller for swelling. 20 ml/kg NS for large burns.","page":148,"deck":"s06"},{"id":"s06c26","front":"Adult head injury ventilation rate and GCS for airway?","back":"10 breaths/min with no herniation signs. GCS 8 or less: intubate or advanced airway.","page":149,"deck":"s06"},{"id":"s06c27","front":"Severe TBI SBP target (adult)?","back":"110–120, even with penetrating trauma and hemorrhage.","page":150,"deck":"s06"},{"id":"s06c28","front":"Signs of increased ICP/herniation (adult)?","back":"GCS drop of 2+, sluggish/nonreactive pupil, one-sided weakness, Cushing's triad.","page":150,"deck":"s06"},{"id":"s06c29","front":"Cushing's triad?","back":"Widening pulse pressure, irregular respirations, bradycardia.","page":150,"deck":"s06"},{"id":"s06c30","front":"Herniation management?","back":"Mild hyperventilation to EtCO2 35, consider advanced airway, head of bed 30°.","page":150,"deck":"s06"},{"id":"s06c31","front":"Why does one hypotensive episode matter in TBI?","back":"It may raise mortality by 150% in adults, and worse in children.","page":150,"deck":"s06"},{"id":"s06c32","front":"Spinal motion restriction: preferred device?","back":"Scoop stretcher, removed once on the stretcher. Backboards are not recommended.","page":152,"deck":"s06"},{"id":"s06c33","front":"SMR criteria (name 5)?","back":"Head trauma, MOI, focal neuro deficit, neck/back pain, distracting injury, AMS with MOI, intoxication with MOI.","page":152,"deck":"s06"},{"id":"s06c34","front":"Prone transport: allowed?","back":"Contraindicated (asphyxiation risk) unless required, e.g. impalement; then document and monitor SpO2/EtCO2 continuously.","page":153,"deck":"s06"},{"id":"s06c35","front":"Helmet rule?","back":"Remove helmets for all patients, with manual c-spine stabilization.","page":153,"deck":"s06"},{"id":"s06c36","front":"Penetrating eye injury care?","back":"Stabilize the object and cover BOTH eyes with gauze and an eye shield.","page":154,"deck":"s06"},{"id":"s06c37","front":"Avulsed tooth?","back":"Rinse with NS, keep moist (cold milk or NS), replace if intact within 30–60 minutes.","page":154,"deck":"s06"},{"id":"s06c38","front":"Chest trauma: fluid target after tension pneumo is ruled out?","back":"Enough to keep peripheral pulses, typically SBP 80–90.","page":155,"deck":"s06"},{"id":"s06c39","front":"Open pneumothorax care?","back":"Vented chest seal or occlusive dressing, applied during exhalation if possible; watch for tension.","page":155,"deck":"s06"},{"id":"s06c40","front":"Needle decompression indications?","back":"Tension pneumo signs plus more than one of: distress and cyanosis, decreasing LOC, loss of radial pulse.","page":156,"deck":"s06"},{"id":"s06c41","front":"Needle decompression site vs finger thoracostomy site?","back":"Needle: 2nd or 3rd intercostal space, midclavicular. Finger: 3rd intercostal space, midaxillary.","page":156,"deck":"s06"},{"id":"s06c42","front":"Crush injury: when does treatment start and what fluids?","back":"Before releasing compression. NS 500 ml–1 L (peds 20 ml/kg). Avoid LR (potassium).","page":157,"deck":"s06"},{"id":"s06c43","front":"Crush syndrome: bicarb and hyperkalemia meds?","back":"Sodium bicarb 1 mEq/kg. For peaked T/wide QRS: calcium chloride 1 g, albuterol 10 mg neb.","page":157,"deck":"s06"},{"id":"s06c44","front":"Evisceration care?","back":"Don't replace it. Moist sterile dressing then dry dressing. Keep the patient calm.","page":158,"deck":"s06"},{"id":"s06c45","front":"Pelvic fracture: assessment rule and devices?","back":"No pelvic rock; gentle pressure once. T-POD, SAM sling or sheet; scoop to move.","page":159,"deck":"s06"},{"id":"s06c46","front":"Pediatric pelvic binder size rules?","back":"T-POD: over 1 year and over 50 lb. SAM sling: over 7 or taller than 4'8\".","page":159,"deck":"s06"},{"id":"s06c47","front":"Posterior vs anterior hip dislocation?","back":"Posterior: flexed and internally rotated. Anterior: externally (laterally) rotated and shortened.","page":160,"deck":"s06"},{"id":"s06c48","front":"Tourniquet placement rule?","back":"Most proximal position on the limb; never over the wound or a joint.","page":161,"deck":"s06"},{"id":"s06c49","front":"Clotting agent: how long to hold pressure?","back":"Pack the wound and hold at least one minute.","page":161,"deck":"s06"},{"id":"s06c50","front":"How many attempts to straighten a deformed extremity?","back":"No more than two; stop with severe pain or resistance.","page":161,"deck":"s06"},{"id":"s06c51","front":"Amputated part handling?","back":"Rinse, wrap in sterile gauze, bag it, then place in ice and water; label with name, date and times.","page":162,"deck":"s06"},{"id":"s06c52","front":"Open fracture antibiotic?","back":"Adults only (or puberty): cefepime 2 g in 10 ml NS, into 100 ml, 1 drop/sec on a 10-drop set (~16 min).","page":162,"deck":"s06"},{"id":"s06c53","front":"Traction splint exclusions?","back":"Other life threats, pelvic or hip fracture, open fracture with exposed bone, ankle/foot avulsion, fracture distal to mid-shaft.","page":163,"deck":"s06"},{"id":"s06c54","front":"Pregnant trauma arrest over 20 weeks: destination?","back":"Closest Trauma/OB center: Broward Health Medical Center or Memorial Regional. Displace the uterus left.","page":164,"deck":"s06"},{"id":"s06c55","front":"How much blood can a pregnant patient lose before showing shock?","back":"30–35% of blood volume.","page":164,"deck":"s06"},{"id":"s06c56","front":"Pregnant patient needing SMR: positioning?","back":"4–6 inches of padding under the right side. Otherwise transport on the left side.","page":164,"deck":"s06"},{"id":"s06c57","front":"3rd-trimester trauma oxygen?","back":"15 L/min by NRB for all.","page":165,"deck":"s06"},{"id":"s07c01","front":"Traumatic arrest: when is resuscitation NOT attempted?","back":"When ALL are present on arrival: apneic, pulseless (asystole), fixed and dilated pupils.","page":170,"deck":"s07"},{"id":"s07c02","front":"Traumatic arrest: where does resuscitation happen and what device is banned?","back":"En route to the trauma center. No mechanical CPR in trauma patients.","page":170,"deck":"s07"},{"id":"s07c03","front":"Electrocution or lightning arrest?","back":"Immediate defibrillation if applicable.","page":170,"deck":"s07"},{"id":"s07c04","front":"MARCHES stands for?","back":"Massive bleeding, Airway, Respiratory, Circulation, Hypothermia, Eyes, Spinal motion restriction.","page":172,"deck":"s07"},{"id":"s07c05","front":"Neurogenic shock presentation?","back":"Warm dry skin, hypotension with bradycardia, paralysis from injury above T6.","page":171,"deck":"s07"},{"id":"s07c06","front":"Neurogenic shock fluids and next step?","back":"500 ml boluses, max 1 L, to a radial pulse (SBP about 90). Still hypotensive: push-dose epi.","page":171,"deck":"s07"},{"id":"s07c07","front":"Permissive hypotension target in internal hemorrhage?","back":"A radial pulse: SBP about 90 (MAP about 65).","page":172,"deck":"s07"},{"id":"s07c08","front":"Adult hemorrhagic shock NS limit?","back":"500 ml boluses, reassessing each time, max 1 L. Then blood per protocol.","page":172,"deck":"s07"},{"id":"s07c09","front":"Pediatric hemorrhagic shock fluids?","back":"20 ml/kg NS to minimum SBP for age; may repeat 1x.","page":173,"deck":"s07"},{"id":"s07c10","front":"Clotting agent pressure time in the hemorrhagic shock protocol?","back":"At least two minutes.","page":173,"deck":"s07"},{"id":"s07c11","front":"What blood product is carried and how much per patient?","back":"Low-titer O+ whole blood, generally one 500 ml unit per patient.","page":174,"deck":"s07"},{"id":"s07c12","front":"Whole blood substitutes if unavailable?","back":"Low-titer liquid plasma or O+ PRBCs; repeat prn x1.","page":174,"deck":"s07"},{"id":"s07c13","front":"Blood confirmation: how many people and what do they check?","back":"Two EMS personnel: number, type, Rh, expiration and amount; both sign the tag.","page":174,"deck":"s07"},{"id":"s07c14","front":"Blood doses adult vs pediatric?","back":"Adult 1–2 units. Peds over 5 (no puberty): 15 ml/kg. Under 5: consult medical direction.","page":174,"deck":"s07"},{"id":"s07c15","front":"Whole blood indications (any one)?","back":"SBP under 70; SBP under 90 with HR 110+; age 65+ with SBP ≤100 and HR ≥100; EtCO2 under 25; EMS-witnessed traumatic arrest; judgment.","page":175,"deck":"s07"},{"id":"s07c16","front":"Shock index formula and severity bands?","back":"HR ÷ SBP. Under 0.6 none, 0.6–1.0 mild, 1.0–1.4 moderate, 1.4+ severe.","page":175,"deck":"s07"},{"id":"s07c17","front":"Blood contraindication and relative contraindications?","back":"Religious objection. Relative: woman of childbearing age without confirmed hemorrhagic shock; under 5.","page":175,"deck":"s07"},{"id":"s07c18","front":"Blood storage: where is it stocked and from whom?","back":"Broward Air Rescue Station 85, from OneBlood.","page":176,"deck":"s07"},{"id":"s07c19","front":"Blood fridge temp checks?","back":"Daily at 7 am and 7 pm, logged.","page":176,"deck":"s07"},{"id":"s07c20","front":"Blood cooler: normal and max time out?","back":"Routine 12 hours, max 24 hours. Freezer insert thaws 20 minutes at shift change.","page":177,"deck":"s07"},{"id":"s07c21","front":"Whole blood shelf life and reorder point?","back":"21 days; contact OneBlood at 72 hours out.","page":177,"deck":"s07"},{"id":"s07c22","front":"Transfusion reaction?","back":"Stop immediately, keep other fluids running, report to the receiving facility, return product and tubing to the blood bank.","page":178,"deck":"s07"},{"id":"s07c23","front":"TXA indications?","back":"Traumatic hemorrhagic shock (whole blood criteria), TBI with GCS under 13, postpartum hemorrhage with shock.","page":179,"deck":"s07"},{"id":"s07c24","front":"TXA contraindications?","back":"Injury over 3 hours old, non-traumatic bleeding, under 5 (consult medical direction).","page":179,"deck":"s07"},{"id":"s07c25","front":"Adult TXA dose and rate?","back":"2 g in 100 ml, 10-drop set at 3 drops/sec, about 5 minutes. Can run with whole blood.","page":179,"deck":"s07"},{"id":"s07c26","front":"Pediatric TXA dose?","back":"Ages 5–11: 15 mg/kg in 100 ml, 3 drops/sec over about 5 min (max adult dose).","page":179,"deck":"s07"},{"id":"s08c01","front":"Florida Poison Control number and what they'll ask?","back":"1-800-222-1222. Patient name, zip code of the call, and a contact number. Document the rep's name.","page":182,"deck":"s08"},{"id":"s08c02","front":"Must Poison Control recommendations be followed?","back":"Yes, whenever possible if the treatment is available, and documented.","page":182,"deck":"s08"},{"id":"s08c03","front":"Overdose oral glucose criteria?","back":"BGL under 60 with AMS, can protect airway/swallow: 15 g. Not under age 2.","page":182,"deck":"s08"},{"id":"s08c04","front":"Why be careful with fluids in overdose?","back":"Many drugs depress the heart; even 500 ml can cause failure. Reassess after each 500 ml.","page":183,"deck":"s08"},{"id":"s08c05","front":"Beta blocker OD: common drugs and extra findings?","back":"Atenolol, carvedilol, metoprolol, propranolol. May also cause hypoglycemia and AMS.","page":184,"deck":"s08"},{"id":"s08c06","front":"Adult beta blocker OD with hypotension?","back":"1 L NS, Poison Control, glucagon 1 mg/min to max 10 mg, Zofran 4 mg prn, pace at 60 (etomidate 10 mg), push-dose epi.","page":184,"deck":"s08"},{"id":"s08c07","front":"Pediatric beta blocker OD glucagon?","back":"1 mg/min (0.5 mg if under 20 kg), max 5 mg.","page":184,"deck":"s08"},{"id":"s08c08","front":"Calcium channel blocker OD: common drugs?","back":"Norvasc, Cardizem, Cardene, Procardia.","page":185,"deck":"s08"},{"id":"s08c09","front":"Adult CCB OD with SBP under 100?","back":"1 L NS, calcium chloride 1 g slow over 2 min, pace at 60 for refractory brady, push-dose epi.","page":185,"deck":"s08"},{"id":"s08c10","front":"Pediatric CCB OD calcium chloride?","back":"20 mg/kg slow over 2 min, repeat every 5–10 min, max 1 g.","page":185,"deck":"s08"},{"id":"s08c11","front":"Cocaine OD with SVT, WCT, HTN or seizure?","back":"Versed 5 mg IV/IO/IN/IM, may repeat 1x. Not if hypotensive.","page":186,"deck":"s08"},{"id":"s08c12","front":"Severely agitated cocaine patient?","back":"Ketamine 4 mg/kg IM (max 400 mg single, 800 mg total). Monitor and EtCO2. Never prone.","page":186,"deck":"s08"},{"id":"s08c13","front":"Cocaine chest pain?","back":"Versed first; if no response, chest pain protocol.","page":186,"deck":"s08"},{"id":"s08c14","front":"TCA overdose: the 4 C's and the mnemonic?","back":"Coma, convulsions, cardiac arrhythmias, acidosis. Mad as a hatter, red as a beet, hot, dry, blind.","page":187,"deck":"s08"},{"id":"s08c15","front":"Adult TCA: when and how much bicarb?","back":"QRS over 0.10 sec (2.5 small boxes): 50 mEq slow every 5 min until resolved, max 150 mEq.","page":187,"deck":"s08"},{"id":"s08c16","front":"Pediatric TCA bicarb trigger and dose?","back":"QRS over 0.08 sec (2 small boxes) or hypotensive after 20 ml/kg: 1 mEq/kg.","page":188,"deck":"s08"},{"id":"s08c17","front":"Narcotic OD goal and the risk of full reversal?","back":"Adequate breathing, not full wake-up. Full reversal can cause non-cardiogenic pulmonary edema and violence.","page":189,"deck":"s08"},{"id":"s08c18","front":"Adult Narcan dose?","back":"0.5–2 mg IV/IO/IM/IN, every 1 minute prn for RR under 12, up to 10 mg.","page":189,"deck":"s08"},{"id":"s08c19","front":"Pediatric Narcan dose and triggers?","back":"0.5 mg IV/IO or 1 mg IN/IM q2–3 min. RR under 20 (child) or 40 (neonate). Max total 10 mg.","page":189,"deck":"s08"},{"id":"s08c20","front":"What to consider before giving Narcan?","back":"Restraints.","page":189,"deck":"s08"},{"id":"s09c01","front":"When are physical restraints allowed?","back":"Immediate risk of harming self or others from impaired judgment (drugs/alcohol, psych, head injury, metabolic, dementia, hypoxia at risk of self-extubation).","page":192,"deck":"s09"},{"id":"s09c02","front":"Restrained patient position?","back":"Supine. Never prone for combative patients (asphyxiation risk).","page":192,"deck":"s09"},{"id":"s09c03","front":"Combative patient escapes from EMS. Pursue?","back":"No, unless they're an immediate threat to the provider. Law enforcement secures the scene.","page":193,"deck":"s09"},{"id":"s09c04","front":"Primary restraint device?","back":"Soft restraints, supplemented by stretcher straps (chest strap never over-tightened).","page":194,"deck":"s09"},{"id":"s09c05","front":"Restraints EMS may NOT apply?","back":"Hard plastic ties, riot cuffs, or anything needing a key. Law enforcement only.","page":194,"deck":"s09"},{"id":"s09c06","front":"Spitting or biting patient adjuncts?","back":"NRB mask with oxygen for spitting; c-collar to limit neck flexion for biting.","page":194,"deck":"s09"},{"id":"s09c07","front":"FLFR SOP on patients in police custody?","back":"Police keep custody and must accompany the patient during transport (SOP Article 1103).","page":194,"deck":"s09"},{"id":"s09c08","front":"Restraint procedure on a backboard?","back":"All four limbs in soft restraints; at least three quick-release straps at torso, hips and knees; one provider controls the head.","page":195,"deck":"s09"},{"id":"s09c09","front":"Restraint documentation and reassessment interval?","back":"Behavior, devices, time applied, and reassessment after application and every 3 minutes.","page":195,"deck":"s09"},{"id":"s09c10","front":"Hyperactive delirium: associated drugs?","back":"Cocaine/crack, PCP, MDMA, meth/amphetamines, Flakka.","page":196,"deck":"s09"},{"id":"s09c11","front":"Adult chemical restraint ketamine dose?","back":"4 mg/kg IM, may repeat 1x. Max single 400 mg, total 800 mg.","page":196,"deck":"s09"},{"id":"s09c12","front":"No ketamine for a violent adult: substitute?","back":"Haldol 5 mg IM + Benadryl 50 mg IM (same syringe OK).","page":196,"deck":"s09"},{"id":"s09c13","front":"Why let a delirium patient hyperventilate?","back":"It compensates for severe acidosis and helps prevent sudden decompensation.","page":196,"deck":"s09"},{"id":"s09c14","front":"Ketamine hypersalivation treatment?","back":"Atropine 1 mg IV/IM/IO.","page":197,"deck":"s09"},{"id":"s09c15","front":"Who is at higher risk of respiratory depression with ketamine?","back":"Over 65, head trauma, under 50 kg, other sedatives (benzos, alcohol).","page":197,"deck":"s09"},{"id":"s09c16","front":"Pediatric ketamine for severe agitation?","back":"1 mg/kg diluted, may repeat 3x. Max IM volume 4 ml. Monitor and EtCO2 mandatory.","page":197,"deck":"s09"},{"id":"s09c17","front":"Who does NOT get pain meds?","back":"Pregnant patients 32+ weeks in active labor, for labor pain. Unrelated pain is still treated.","page":198,"deck":"s09"},{"id":"s09c18","front":"Adult fentanyl for moderate-severe pain?","back":"50 mcg slow IV/IO/IM/IN, repeat after 5 min prn, max 200 mcg.","page":198,"deck":"s09"},{"id":"s09c19","front":"Adult pain ketamine dose and when it's first-line?","back":"25 mg, repeat 2x q5 min, max 75 mg. First-line if hypotensive or opioid contraindicated.","page":198,"deck":"s09"},{"id":"s09c20","front":"Toradol dose and exclusions?","back":"15 mg IV/IO or 30 mg IM, one dose. Not under 18, cardiac chest pain, TBI, or over 20 weeks pregnant.","page":198,"deck":"s09"},{"id":"s09c21","front":"Toradol is ideal for which complaints?","back":"Musculoskeletal injury and kidney stones.","page":198,"deck":"s09"},{"id":"s09c22","front":"Adult IO lidocaine?","back":"40 mg IO over 1 min (over 20 kg), dwell 1 min, flush 10 ml; may give another 40 mg.","page":198,"deck":"s09"},{"id":"s09c23","front":"Pediatric fentanyl IV vs IN?","back":"1 mcg/kg diluted IV/IO over 2 min; 1.5 mcg/kg IN/IM. Max single 100, total 200 mcg.","page":199,"deck":"s09"},{"id":"s09c24","front":"Pediatric ketamine for pain: age?","back":"Over 12, after max fentanyl: 25 mg IM.","page":199,"deck":"s09"},{"id":"s09c25","front":"Fentanyl chest wall rigidity: cause and fix?","back":"Pushing too fast. Reverse with Narcan.","page":199,"deck":"s09"},{"id":"s09c26","front":"Suboxone (future protocol): COWS threshold and dose?","back":"COWS 5 or higher with consent: 16 mg SL, then 8 mg if no response in 15 min.","page":201,"deck":"s09"},{"id":"s09c27","front":"Suboxone exclusions?","back":"AMS/no capacity, won't give name/DOB/phone, refuses transport, pregnant, methadone in 48 h, allergy.","page":201,"deck":"s09"},{"id":"s10c01","front":"Decompression sickness: which divers count as a dive emergency?","back":"Stroke-like signs after SCUBA/compressed air within 48 hours.","page":205,"deck":"s10"},{"id":"s10c02","front":"Decompression sickness: position, fluids and destination?","back":"Supine, 1 L NS (KVO if SOB/hemoptysis), nearest ED with a helipad.","page":205,"deck":"s10"},{"id":"s10c03","front":"Dive emergency contacts and chambers?","back":"DAN hotline 1-800-662-3637. Chambers: Mercy Miami or St. Mary's Palm Beach. Air Rescue max 500 ft.","page":205,"deck":"s10"},{"id":"s10c04","front":"Diver in cardiac arrest: destination?","back":"Closest ED.","page":205,"deck":"s10"},{"id":"s10c05","front":"Drowning: when is c-spine needed?","back":"Only if circumstances suggest spinal injury: diving, rough surf, vehicle submersion.","page":206,"deck":"s10"},{"id":"s10c06","front":"Drowning arrest: priority and gold standard?","back":"Immediate ventilation; ETT is the gold standard (SALAD technique).","page":206,"deck":"s10"},{"id":"s10c07","front":"When can a drowning victim be pronounced on scene?","back":"Only if temperature is over 90°F (32°C).","page":206,"deck":"s10"},{"id":"s10c08","front":"Non-fatal drowning: transport and CPAP?","back":"All must be transported. CPAP 10 for pulmonary edema if over 30 kg.","page":206,"deck":"s10"},{"id":"s10c09","front":"Heat stroke signs?","back":"AMS, seizures, hypotension, tachycardia, red hot flushed skin; sweating may be absent.","page":208,"deck":"s10"},{"id":"s10c10","front":"Heat stroke: temperature for rapid cooling and method?","back":"Over 103°F: ice packs to axilla and groin (no shivering), chilled NS 1 L, mist and fan.","page":208,"deck":"s10"},{"id":"s10c11","front":"Snake bite: what NOT to do?","back":"No ice, tourniquets or constricting bands. Mark the swelling; keep the limb below the heart.","page":210,"deck":"s10"},{"id":"s10c12","front":"Snake bite meds (adult)?","back":"Benadryl 50 mg and Solu-Medrol 125 mg. Peds: 1 mg/kg and 2 mg/kg.","page":210,"deck":"s10"},{"id":"s10c13","front":"Venom One number?","back":"786-229-0736.","page":210,"deck":"s10"},{"id":"s10c14","front":"Bee stinger removal?","back":"Scrape it off with a flat edge (credit card); don't pull it.","page":211,"deck":"s10"},{"id":"s10c15","front":"Stingray/lionfish/sea urchin puncture?","back":"Immerse in non-scalding hot water, wash and irrigate.","page":211,"deck":"s10"},{"id":"s10c16","front":"Jellyfish/man-of-war sting?","back":"Rinse with sea water. No fresh water, ice or rubbing. Remove tentacles with forceps, upwind.","page":211,"deck":"s10"},{"id":"s10c17","front":"CO: toxic concentration?","back":"Above 35 ppm; lower doses add up.","page":212,"deck":"s10"},{"id":"s10c18","front":"CO poisoning treatment and destination?","back":"SCBA for rescuers, NRB 15 L/min, SpCO (Rainbow sensor), closest ED with a helipad.","page":212,"deck":"s10"},{"id":"s10c19","front":"Who gets strong hyperbaric consideration in CO exposure?","back":"All pediatric and obstetric patients with confirmed exposure, regardless of SpCO or symptoms.","page":212,"deck":"s10"},{"id":"s10c20","front":"Why can SpO2 be misleading in CO?","back":"Pulse ox can read normal while the patient is hypoxic.","page":212,"deck":"s10"},{"id":"s10c21","front":"Signs highly suggestive of cyanide poisoning?","back":"AMS and/or pupil dilation.","page":213,"deck":"s10"},{"id":"s10c22","front":"Adult Cyanokit dose?","back":"5 g over 10–15 min on a dedicated line; may repeat once (max 10 g). Alert the Battalion Chief.","page":213,"deck":"s10"},{"id":"s10c23","front":"Pediatric Cyanokit dose?","back":"70 mg/kg, max single 5 g; may repeat once.","page":213,"deck":"s10"},{"id":"s11c01","front":"Gravida vs para?","back":"Gravida: number of pregnancies. Para: number of viable births.","page":216,"deck":"s11"},{"id":"s11c02","front":"What defines an OB patient?","back":"20 weeks or more. Under 20 weeks is GYN: closest ED.","page":216,"deck":"s11"},{"id":"s11c03","front":"Over 20 weeks: destination rules?","back":"Abdominal/pelvic pain or constitutional symptoms: closest OB hospital. Minor issue: closest ED. Stable: OB hospital of choice within 40 min (Section 1.4 says 30 min; check which applies).","page":216,"deck":"s11"},{"id":"s11c04","front":"Over 20 weeks in arrest or with trauma: destination?","back":"Arrest: closest OB hospital. Trauma: Trauma/OB hospital.","page":216,"deck":"s11"},{"id":"s11c05","front":"Classic ectopic signs?","back":"Amenorrhea, vaginal bleeding and abdominal pain; left shoulder pain, Cullen's or Grey Turner's sign.","page":217,"deck":"s11"},{"id":"s11c06","front":"Fetus over 22 weeks still in the sac?","back":"Open the sac, cut the cord and start neonatal resuscitation.","page":217,"deck":"s11"},{"id":"s11c07","front":"Abruptio vs previa?","back":"Abruptio: sudden severe pain, painful contractions, dark red bleeding, shock. Previa: painless bright red bleeding.","page":218,"deck":"s11"},{"id":"s11c08","front":"Uterine rupture signs?","back":"Sudden intense pain and bleeding; abnormal abdominal contour, palpable fetal parts, asymmetry.","page":218,"deck":"s11"},{"id":"s11c09","front":"Third-trimester positioning?","back":"Left side by raising the right side 4–6 inches, or manually displace the uterus left.","page":218,"deck":"s11"},{"id":"s11c10","front":"Severe pre-eclampsia definition?","back":"Over 20 weeks, SBP over 140 or DBP over 90 twice 5 min apart, plus AMS, headache, visual changes, edema or clonus.","page":219,"deck":"s11"},{"id":"s11c11","front":"How long after delivery can eclampsia occur?","back":"Up to 45 days postpartum.","page":219,"deck":"s11"},{"id":"s11c12","front":"Pre-eclampsia treatment?","back":"Mag 2 g in 100 ml wide open; labetalol 20 mg IV push, 1 dose max.","page":219,"deck":"s11"},{"id":"s11c13","front":"Eclampsia (actively seizing) bundle?","back":"Mag 4 g IV/IO wide open AND 2 g IM; labetalol 20 mg; seizure protocol.","page":219,"deck":"s11"},{"id":"s11c14","front":"Eclampsia with no IV/IO?","back":"Mag 6 g IM split across 3 sites.","page":219,"deck":"s11"},{"id":"s11c15","front":"What does positive clonus mean?","back":"Rhythmic 'flickering' after rapid ankle dorsiflexion: CNS hyperexcitability, seizure imminent.","page":219,"deck":"s11"},{"id":"s11c16","front":"When is the cord clamped and how?","back":"After it stops pulsing and turns white (3–5 min). Clamp 6 in from baby, milk toward mom, second clamp 2 in further, cut between.","page":220,"deck":"s11"},{"id":"s11c17","front":"Placenta delivery time and rule?","back":"Spontaneous in 5–30 min. Never pull on the cord.","page":220,"deck":"s11"},{"id":"s11c18","front":"APGAR timing and a typical 1-minute score?","back":"1 and 5 minutes. A 1-minute score of 8 is common.","page":221,"deck":"s11"},{"id":"s11c19","front":"APGAR components?","back":"Appearance, Pulse (over 100 = 2), Grimace, Activity, Respirations.","page":221,"deck":"s11"},{"id":"s11c20","front":"After the placenta delivers?","back":"Firm fundal massage; bag the placenta for the hospital.","page":221,"deck":"s11"},{"id":"s11c21","front":"Breech: head not delivered in 3 minutes?","back":"Knee-to-chest, gloved hand to push the vaginal wall off the baby's nose and mouth, expedite, blow-by O2.","page":222,"deck":"s11"},{"id":"s11c22","front":"Shoulder dystocia signs?","back":"Turtle sign, shoulders won't deliver with gentle traction, head-to-body over 60 seconds.","page":223,"deck":"s11"},{"id":"s11c23","front":"Shoulder dystocia management?","back":"McRoberts (knees hyperflexed to chest) plus suprapubic pressure. NEVER fundal pressure.","page":223,"deck":"s11"},{"id":"s11c24","front":"Nuchal cord?","back":"Slip the loop over the head; if too tight, clamp twice and cut between.","page":224,"deck":"s11"},{"id":"s11c25","front":"Prolapsed cord?","back":"Knee-to-chest, uterus left, gloved hand pushes baby off the cord (pulse or not), moist dressing, closest OB.","page":225,"deck":"s11"},{"id":"s11c26","front":"Postpartum hemorrhage definition and 4 T's?","back":"Over 500 ml after vaginal delivery. Tone, Trauma, Tissue, Thrombin.","page":226,"deck":"s11"},{"id":"s11c27","front":"PPH Pitocin dose?","back":"10 units IM lateral thigh, one dose, even without shock criteria. Plus massage, TXA and blood per protocol.","page":226,"deck":"s11"},{"id":"s11c28","front":"Neonatal ventilation rate and compression ratio?","back":"40 breaths/min. 3:1 compressions to ventilations.","page":227,"deck":"s11"},{"id":"s11c29","front":"Neonatal HR decision points?","back":"Apnea or HR under 100: PPV. HR under 60: compressions. Still under 60: push-dose epi.","page":227,"deck":"s11"},{"id":"s11c30","front":"Neonatal resus: what's checked on every infant needing resuscitation?","back":"Blood glucose.","page":227,"deck":"s11"},{"id":"s11c31","front":"Delayed cord clamping?","back":"At least 30–60 seconds for vigorous infants. No cord milking under 28 weeks if resuscitation is needed.","page":228,"deck":"s11"},{"id":"s11c32","front":"Neonatal initial oxygen?","back":"Term: room air (21%). Preterm under 35 weeks: 3 L NC, titrate to pulse ox.","page":228,"deck":"s11"},{"id":"s11c33","front":"The Golden Minute?","back":"Every baby who isn't breathing gets PPV within 60 seconds. PEEP 5 encouraged.","page":228,"deck":"s11"},{"id":"s11c34","front":"Preferred neonatal HR monitoring?","back":"4-lead ECG (pulse ox is for O2 titration).","page":228,"deck":"s11"},{"id":"s11c35","front":"Neonatal LMA criteria?","back":"34 weeks or 2,000 g or more, when mask ventilation fails and intubation isn't possible.","page":229,"deck":"s11"},{"id":"s12c01","front":"12-lead timing rules for critical patients?","back":"Treat life threats first; a 12-lead must not delay transport.","page":234,"deck":"s12"},{"id":"s12c02","front":"When do you run a V4R and how?","back":"ST changes in II, III or aVF. Move V4 to the right 5th ICS midclavicular and manually print it.","page":234,"deck":"s12"},{"id":"s12c03","front":"Precordial lead placement V1–V6?","back":"V1/V2: 4th ICS right/left of sternum. V4: 5th ICS midclavicular. V3 between V2 and V4. V5 anterior axillary. V6 midaxillary.","page":235,"deck":"s12"},{"id":"s12c04","front":"Blood alcohol draw: statute and rules?","back":"FS 316.1932. In the back of the rescue, LE-supplied kit only, never an alcohol prep; give the sample to the officer.","page":237,"deck":"s12"},{"id":"s12c05","front":"Blood alcohol documentation?","back":"Kit used, requesting officer's name, time of draw, BGL. Never 'clear' the patient.","page":237,"deck":"s12"},{"id":"s12c06","front":"Glucometer codes LO, HI, KETONES?","back":"LO under 20; HI over 500; KETONES over 300. Repeat abnormal results with a new strip.","page":238,"deck":"s12"},{"id":"s12c07","front":"Where NOT to draw a glucose sample?","back":"From an IV site (venous sampling not approved).","page":238,"deck":"s12"},{"id":"s12c08","front":"SpCO sensor site preference?","back":"Ring, then middle, then index finger (ear lobe or forehead OK). Shield from ambient light.","page":239,"deck":"s12"},{"id":"s12c09","front":"SpO2 reading that may call for aggressive oxygenation?","back":"Below 90%.","page":240,"deck":"s12"},{"id":"s12c10","front":"Bougie: smallest ETT and contraindication?","back":"Fits down to a 6.0. Not for nasal intubation.","page":242,"deck":"s12"},{"id":"s12c11","front":"Bougie: tracheal vs esophageal signs?","back":"Trachea: clicks on the rings and stops (resistance). Esophagus: no clicks, advances freely.","page":242,"deck":"s12"},{"id":"s12c12","front":"Tube hangs up at the cords on a bougie?","back":"Pull back 1–2 cm, rotate 90° counterclockwise, re-advance.","page":243,"deck":"s12"},{"id":"s12c13","front":"CPAP absolute contraindications (name 5)?","back":"SBP under 90, apnea, lethargy/no gag, suspected pneumothorax, unstable facial fractures, laryngeal trauma, under 30 kg.","page":244,"deck":"s12"},{"id":"s12c14","front":"CPAP and nebulizer interaction?","back":"Pressure drops when the neb runs and rises when it stops; verify with the manometer.","page":244,"deck":"s12"},{"id":"s12c15","front":"Needle cric: age and technique?","back":"10 and under. 14g catheter with a 10 ml syringe, 45–60° caudal, aspirate air.","page":247,"deck":"s12"},{"id":"s12c16","front":"Needle cric ventilation ratio?","back":"1:3 I:E (1-second breath, 3 seconds out). Doesn't protect the airway or clear CO2.","page":247,"deck":"s12"},{"id":"s12c17","front":"Surgical cric: contraindication and incision?","back":"Not for age 10 or under. 2 cm horizontal incision through the membrane (optional 2–4 cm vertical first).","page":248,"deck":"s12"},{"id":"s12c18","front":"Cricothyroid membrane landmark?","back":"Between the thyroid cartilage (1st prominence) and cricoid cartilage (2nd).","page":247,"deck":"s12"},{"id":"s12c19","front":"Orotracheal confirmation?","back":"Waveform capnography, no epigastric sounds, lung sounds, tube condensation.","page":249,"deck":"s12"},{"id":"s12c20","front":"Nasotracheal: age and contraindications?","back":"Puberty and up, breathing spontaneously. Not with apnea, FBAO, severe head injury/basilar skull fracture, bleeding disorders.","page":250,"deck":"s12"},{"id":"s12c21","front":"Nasotracheal tube size?","back":"Usually 0.5 mm smaller than the oral tube; advance on inhalation.","page":250,"deck":"s12"},{"id":"s12c22","front":"i-gel sizes by weight?","back":"1: 2–5 kg; 1.5: 5–12; 2: 10–25; 2.5: 25–35; 3: 30–60; 4: 50–90; 5: 90+.","page":251,"deck":"s12"},{"id":"s12c23","front":"i-gel contraindications?","back":"Intact gag, trismus/limited opening, pharyngeal abscess, trauma or mass.","page":251,"deck":"s12"},{"id":"s12c24","front":"Gastric tube contraindications?","back":"Caustic ingestion, esophageal tumors/varices, major facial trauma, pediatrics, basilar skull fracture.","page":255,"deck":"s12"},{"id":"s12c25","front":"Gastric tube: measure and confirm?","back":"Stomach to ear to nose tip. Confirm with 20–30 ml air while listening over the epigastrium.","page":255,"deck":"s12"},{"id":"s12c26","front":"SSCOR suction: contraindication?","back":"Neonates; its minimum suction is too strong.","page":258,"deck":"s12"},{"id":"s12c27","front":"Meconium suction limits?","back":"No higher than 100 mmHg, no more than 5 seconds at a time. Meconium alone isn't an indication.","page":259,"deck":"s12"},{"id":"s12c28","front":"SALAD: key step?","back":"Park the rigid suction catheter in the esophagus with continuous suction, then laryngoscope alongside it.","page":261,"deck":"s12"},{"id":"s12c29","front":"Synchronized cardioversion: rate rule and caution?","back":"Generally unnecessary under 150. Re-enable sync before EACH shock; critical delay = unsynchronized.","page":262,"deck":"s12"},{"id":"s12c30","front":"Pacing pad position and pulse check?","back":"Anterior–posterior preferred (anterior–lateral with SMR or defib). Check femoral/brachial/radial, not carotid.","page":263,"deck":"s12"},{"id":"s12c31","front":"Approved IO sites?","back":"Proximal humerus, tibial tuberosity, medial malleolus, distal femur.","page":264,"deck":"s12"},{"id":"s12c32","front":"IO needle sizes?","back":"15 mm pink: 3–39 kg. 25 mm blue: 3 kg+. 45 mm yellow: 40 kg+ (humerus/femur in adults).","page":264,"deck":"s12"},{"id":"s12c33","front":"IO rule for flow?","back":"No flush = no flow: rapid 10 ml NS flush first (10–20 ml after placement).","page":264,"deck":"s12"},{"id":"s12c34","front":"IO contraindications?","back":"Fracture in that bone, no landmarks, recent IO/prosthesis/joint replacement, infection at site.","page":264,"deck":"s12"},{"id":"s12c35","front":"IO site preference adult vs pediatric?","back":"Adult: humerus, proximal tibia, distal femur. Infant/child: distal femur first.","page":267,"deck":"s12"},{"id":"s12c36","front":"IO removal time limit?","back":"Within 24 hours of insertion.","page":269,"deck":"s12"},{"id":"s12c37","front":"Nebulizer O2 flow?","back":"6 L/min; inhale slowly and hold 3–5 seconds.","page":270,"deck":"s12"},{"id":"s12c38","front":"Nerve agent signs and auto-injector hold time?","back":"Pinpoint pupils, SLUDGE, breathing trouble, seizures. Hold at least 10 seconds.","page":271,"deck":"s12"},{"id":"s12c39","front":"Chest seal: when to apply?","back":"Proactively on any open chest, neck or abdominal wound of unknown depth; valve over the wound.","page":272,"deck":"s12"},{"id":"s12c40","front":"Helmet removal: motorcycle vs football?","back":"All motorcycle helmets come off. Football: if the airway is needed, pads must come off, or the head is loose.","page":273,"deck":"s12"},{"id":"s12c41","front":"Morgan lens: indications and contraindications?","back":"Adults with non-penetrating eye injury. Not for kids or impaled objects.","page":277,"deck":"s12"},{"id":"s12c42","front":"Pelvic binder placement?","back":"Centered over the greater trochanters, not the iliac crests. TPOD: leave a 6–8 in gap before tightening.","page":279,"deck":"s12"},{"id":"s12c43","front":"Finger thoracostomy indications?","back":"Tension pneumo, hemothorax with hypotension or can't ventilate, traumatic arrest.","page":281,"deck":"s12"},{"id":"s12c44","front":"Traction splint contraindications?","back":"Other fractures of the same leg, foot/ankle fracture, hip, pelvic or knee injury.","page":283,"deck":"s12"},{"id":"s12c45","front":"Tourniquet placement?","back":"2–3 inches above the wound, never over a joint; high and tight if the wound can't be found.","page":285,"deck":"s12"},{"id":"s12c46","front":"Tourniquet still bleeding? Time concern?","back":"Add a second one proximal to the first. Over 6 hours risks tissue loss.","page":286,"deck":"s12"},{"id":"s12c47","front":"Intranasal volume?","back":"0.2–0.3 ml per nostril, max 0.5 ml. Don't let them sniff; aim toward the top of the ear.","page":288,"deck":"s12"},{"id":"s12c48","front":"PEEP valve: start setting and contraindications?","back":"5 cmH2O. Avoid with untreated pneumothorax, hypotension/hypovolemia, severe air trapping.","page":289,"deck":"s12"},{"id":"s13c01","front":"Push-dose epi: how is it mixed and what concentration results?","back":"9 ml NS + 1 ml epi 1:10,000 = 10 ml of 1:100,000 (10 mcg/ml).","page":293,"deck":"s13"},{"id":"s13c02","front":"Push-dose epi: how is it given and what is the max?","back":"1 ml every 30 seconds IV/IO, titrated to SBP over 100 (age-appropriate in peds). May repeat 2x; max total 0.3 mg.","page":293,"deck":"s13"},{"id":"s13c03","front":"Pediatric IV/IO Benadryl dilution?","back":"Dilute with 9 ml NS to make 5 mg/ml.","page":293,"deck":"s13"},{"id":"s13c04","front":"IV ketamine dilution?","back":"All IV ketamine is diluted to 10 mg/ml: 500 mg in 50 ml NS, or for pain, 1 ml of 100 mg/ml into a 10 ml syringe with 1 ml saline removed.","page":293,"deck":"s13"},{"id":"s13c05","front":"Pediatric IV/IO fentanyl dilution?","back":"2 ml (100 mcg) in 8 ml NS = 10 mcg/ml.","page":293,"deck":"s13"},{"id":"s13c06","front":"Sodium bicarb for infants and neonates (under 5)?","back":"Dilute to 4.2%: discard 25 ml of 8.4% and draw up 25 ml NS.","page":293,"deck":"s13"},{"id":"s13c07","front":"Adult amiodarone and mag infusions: mix and rate?","back":"Amio 150 mg in 100 ml; mag 2 g in 100 ml. Both on a 10-drop set at 1 drop/sec (6 ml/min), about 16 minutes.","page":294,"deck":"s13"},{"id":"s13c08","front":"Pediatric respiratory rate ranges?","back":"Neonate 40–60, infant 30–60, toddler 24–40, preschool 22–34, school age 18–30, adolescent 12–16.","page":295,"deck":"s13"},{"id":"s13c09","front":"Pediatric heart rate ranges?","back":"Newborn–3 mo 85–205; 3 mo–2 yr 100–190; 2–10 yr 60–140; over 10: 60–100.","page":295,"deck":"s13"},{"id":"s13c10","front":"Adenosine indication and concentration?","back":"SVT with rates over 150. Supplied 12 mg in 4 ml (3 mg/ml).","page":297,"deck":"s13"},{"id":"s13c11","front":"Adenosine contraindications?","back":"2nd/3rd-degree AV block (unless paced), sick sinus without a pacer, carbamazepine (Tegretol), active bronchospasm, heart transplant.","page":297,"deck":"s13"},{"id":"s13c12","front":"How is adenosine pushed?","back":"18g in the AC if possible, port closest to the site, start ECG recording, then rapid push with a 20 ml NS flush over 1–2 seconds.","page":297,"deck":"s13"},{"id":"s13c13","front":"Amiodarone contraindications?","back":"Torsades, cardiogenic shock, hypotension, marked sinus brady, 2nd/3rd-degree block, pregnancy.","page":299,"deck":"s13"},{"id":"s13c14","front":"Amiodarone concentration and a handling tip?","back":"150 mg/3 ml (50 mg/ml). Don't shake the vial: it foams. Half-life can last up to 40 days.","page":299,"deck":"s13"},{"id":"s13c15","front":"Aspirin contraindications?","back":"Allergy, salicylate sensitivity, GI bleed, active ulcer, hemorrhagic stroke, bleeding disorders, under 16.","page":300,"deck":"s13"},{"id":"s13c16","front":"Atropine minimum doses and why?","back":"No less than 0.5 mg adult or 0.1 mg pediatric. Pushed too slowly it can initially slow the heart.","page":301,"deck":"s13"},{"id":"s13c17","front":"Atropine indications?","back":"Symptomatic bradycardia, organophosphates, ketamine adverse reaction, RSI.","page":301,"deck":"s13"},{"id":"s13c18","front":"Calcium chloride indications?","back":"CCB overdose, hyperkalemia (peaked T, wide QRS, sine wave), Cardizem-induced hypotension.","page":303,"deck":"s13"},{"id":"s13c19","front":"Calcium chloride: line caution and concentration?","back":"Don't run with sodium bicarb without flushing (precipitates). 1 g/10 ml.","page":303,"deck":"s13"},{"id":"s13c20","front":"Cardizem contraindications?","back":"Hypotension, wide QRS, heart blocks, WPW, sick sinus. Not for OB patients.","page":304,"deck":"s13"},{"id":"s13c21","front":"Cardizem-induced hypotension treatment?","back":"Calcium chloride 500 mg and 500 ml NS.","page":304,"deck":"s13"},{"id":"s13c22","front":"Cefepime indications and contraindication?","back":"Sepsis with 2 qSOFA criteria, open fracture. Contraindicated with cephalosporin allergy (not PCN).","page":305,"deck":"s13"},{"id":"s13c23","front":"Cyanokit: who carries it and how is it mixed?","back":"EMS Supervisor and HazMat units only. 5 g vial + 200 ml NS, rock 30 seconds, don't shake. Dedicated line.","page":307,"deck":"s13"},{"id":"s13c24","front":"Cyanokit: what to draw first and common side effect?","back":"A purple-top tube before treatment (it interferes with labs). Red urine (chromaturia).","page":306,"deck":"s13"},{"id":"s13c25","front":"D10 vs D50 grams?","back":"D10: 10 g per 100 ml (25 g in 250 ml). D50: 25 g per amp.","page":308,"deck":"s13"},{"id":"s13c26","front":"Epinephrine contraindication and caution?","back":"Contraindicated in hypovolemic shock. Caution over age 50 with HTN, tachycardia, or pregnancy.","page":309,"deck":"s13"},{"id":"s13c27","front":"Etomidate onset, duration and concentration?","back":"Unconscious within 60 seconds, lasts 3–15 min. 20 mg/10 ml (2 mg/ml).","page":310,"deck":"s13"},{"id":"s13c28","front":"Etomidate: why only rapid push in RSI?","back":"Rapid push can cause trismus; that's acceptable only in RSI.","page":310,"deck":"s13"},{"id":"s13c29","front":"Fentanyl equivalence and duration?","back":"100 mcg ≈ 10 mg morphine. Lasts 30–60 min after one IV dose.","page":311,"deck":"s13"},{"id":"s13c30","front":"Fentanyl concentration, routes and a rapid-push risk?","back":"50 mcg/ml; IV, IO, IN, IM. Rapid IV push can cause rigid chest wall syndrome.","page":311,"deck":"s13"},{"id":"s13c31","front":"Glucagon: when is it used and a needle warning?","back":"Hypoglycemia when no IV/IO. The supplied needle is NOT for IM; switch needles.","page":312,"deck":"s13"},{"id":"s13c32","front":"Haldol contraindications?","back":"Combativeness from trauma, Parkinson's, coma, seizure disorders, CNS depression, cocaine OD, others.","page":313,"deck":"s13"},{"id":"s13c33","front":"Ketamine contraindications?","back":"Allergy and penetrating eye injury.","page":314,"deck":"s13"},{"id":"s13c34","front":"Ketamine laryngospasm: order of correction?","back":"High-flow O2, then BVM, then advanced airway (RSI).","page":314,"deck":"s13"},{"id":"s13c35","front":"Lasix indication and key contraindications?","back":"Cardiogenic pulmonary edema, adults only. Not with sulfa allergy, pregnancy, hypovolemia, anuria, sepsis/pneumonia/fever.","page":315,"deck":"s13"},{"id":"s13c36","front":"Lidocaine's only listed indication in the formulary?","back":"IO pain management.","page":316,"deck":"s13"},{"id":"s13c37","front":"Labetalol: indication and dose?","back":"Severe pre-eclampsia/eclampsia ONLY. 20 mg IV/IO over 2 min. Mag is first-line for seizures.","page":317,"deck":"s13"},{"id":"s13c38","front":"Magnesium indications and contraindication?","back":"Pre-eclampsia, eclampsia, torsades, severe asthma. Contraindicated in 2nd/3rd-degree block.","page":318,"deck":"s13"},{"id":"s13c39","front":"Narcan: what do you titrate to?","back":"Adequate respiratory drive by EtCO2 and SpO2, not full wake-up.","page":320,"deck":"s13"},{"id":"s13c40","front":"Narcan: which opioids may need higher doses?","back":"Methadone, Darvon, Talwin and fentanyl; contact medical control.","page":321,"deck":"s13"},{"id":"s13c41","front":"NTG paste contraindications?","back":"Hypotension, ED drugs (sildenafil/Levitra 24 h, Cialis 48 h), RV infarct, no IV/IO.","page":322,"deck":"s13"},{"id":"s13c42","front":"NTG-induced hypotension?","back":"Supine, 500 ml NS bolus, remove the paste.","page":322,"deck":"s13"},{"id":"s13c43","front":"Nitrous oxide contraindications (name 5)?","back":"Any altered LOC, COPD, pulmonary edema, pneumothorax, decompression sickness, distended abdomen, pregnancy (except delivery), can't self-administer.","page":323,"deck":"s13"},{"id":"s13c44","front":"Oral glucose criteria?","back":"BGL under 60 in a patient who can swallow and protect their airway.","page":325,"deck":"s13"},{"id":"s13c45","front":"Oxytocin: when is it given?","back":"Postpartum hemorrhage after baby AND placenta delivered, not controlled by fundal massage and nursing.","page":327,"deck":"s13"},{"id":"s13c46","front":"Rocuronium onset, duration, concentration?","back":"1–2 min onset, 30–60 min duration. 10 mg/ml; reconstitute with 10 ml NS.","page":328,"deck":"s13"},{"id":"s13c47","front":"Sodium bicarb indications?","back":"Hyperkalemia, agitated delirium, arrest/ROSC, digitalis toxicity, TCA OD, crush injury, certain HazMat toxidromes.","page":329,"deck":"s13"},{"id":"s13c48","front":"Toradol: age limit and onset?","back":"Not under 18. Onset about 10 min IV, 30–60 min IM; lasts 4–6 hours.","page":332,"deck":"s13"},{"id":"s13c49","front":"Versed onset, contraindication and concentration?","back":"1–5 min IV, 15 min IM. Contraindicated in narrow-angle glaucoma. 5 mg/2 ml (2.5 mg/ml).","page":333,"deck":"s13"},{"id":"s13c50","front":"Zofran contraindications?","back":"Hypersensitivity, pregnancy, QTc over 500 ms; caution in hepatic impairment.","page":334,"deck":"s13"},{"id":"s13c51","front":"Pediatric weight-based doses: epi 1:10,000, atropine, CaCl, D10?","back":"Epi 0.01 mg/kg, atropine 0.02 mg/kg, calcium chloride 20 mg/kg, D10 5 ml/kg.","page":336,"deck":"s13"},{"id":"s13c52","front":"Pediatric weight-based doses: adenosine, Narcan, Versed?","back":"Adenosine 0.1 then 0.2 mg/kg, Narcan 0.1 mg/kg, Versed 0.1 mg/kg IV or 0.2 mg/kg IN/IM.","page":336,"deck":"s13"},{"id":"s14c01","front":"HazMat supportive care first steps?","back":"Remove from the hazard, strip and decon with lots of water, irrigate eyes with NS (never neutralize), call Poison Control.","page":350,"deck":"s14"},{"id":"s14c02","front":"Non-cardiogenic pulmonary edema from a chemical?","back":"Ventilate, suction, and use PEEP or CPAP.","page":350,"deck":"s14"},{"id":"s14c03","front":"Mass vs emergency vs technical decon?","back":"Mass: large groups through fog curtains. Emergency: life-threatened victims first. Technical: HazMat team's full decon line.","page":350,"deck":"s14"},{"id":"s14c04","front":"How much contaminant does removing clothing remove?","back":"80–90%.","page":350,"deck":"s14"},{"id":"s14c05","front":"Decon by solubility?","back":"1% soluble or less: water only. More than 1%: soap, clothing removal, then scrubs.","page":350,"deck":"s14"},{"id":"s14c06","front":"Acid vs alkali burns: tissue damage type?","back":"Acid: coagulative necrosis (scab). Alkali: liquefactive necrosis (no scab).","page":351,"deck":"s14"},{"id":"s14c07","front":"Organophosphate/nerve agent atropine (adult)?","back":"2–6 mg IV every 5 min until secretions dry; no max. Mild 2, moderate 4, severe 6 mg.","page":353,"deck":"s14"},{"id":"s14c08","front":"Atropine caution in organophosphate poisoning?","back":"Use extreme caution if hypoxic: may trigger VF.","page":353,"deck":"s14"},{"id":"s14c09","front":"2-PAM: dose and when NOT to use?","back":"1 g IV over 2 min. Not for known carbamate poisoning.","page":353,"deck":"s14"},{"id":"s14c10","front":"Pediatric atropine for organophosphates?","back":"0.02–0.04 mg/kg, never less than 0.1 mg, repeat until atropinized.","page":352,"deck":"s14"},{"id":"s14c11","front":"Hydrofluoric acid: why is pain treated with calcium?","back":"HF binds calcium and magnesium; pain is from that, so treat with calcium, not analgesics. Skin may look normal.","page":354,"deck":"s14"},{"id":"s14c12","front":"HF skin burn treatment?","back":"Flush with water, then calcium gluconate gel (10 ml of 10% in a 2 oz tube of jelly).","page":354,"deck":"s14"},{"id":"s14c13","front":"HF systemic signs needing medical control?","back":"Dysrhythmias, conduction problems, ST changes, tetany, seizures.","page":354,"deck":"s14"},{"id":"s14c14","front":"HF systemic calcium gluconate dose?","back":"Adult 10% 1–2 g (10–20 ml) slow IV over 5 min. Peds 0.2–0.3 ml/kg.","page":355,"deck":"s14"},{"id":"s14c15","front":"HF inhalation treatment?","back":"Nebulize 3 ml of 10% calcium gluconate in 6 ml sterile water.","page":355,"deck":"s14"},{"id":"s14c16","front":"Closed space fire: three injury mechanisms?","back":"Thermal, pulmonary irritation, chemical asphyxiation (HCN and CO).","page":356,"deck":"s14"},{"id":"s14c17","front":"Cyanokit in the HazMat protocol: mix and rate?","back":"5 g vial with 200 ml NS, rock don't shake, dedicated line, 15 ml/min.","page":357,"deck":"s14"},{"id":"s14c18","front":"Pediatric Cyanokit by age (HazMat chart)?","back":"0–5: ¼ bottle (1,250 mg). 6–14: ½ bottle (2,500 mg). 15+: full 5 g.","page":357,"deck":"s14"},{"id":"s14c19","front":"Cyanide: odor and pulse ox clue?","back":"Bitter almonds (some can smell it). SpO2 reads unusually high.","page":358,"deck":"s14"},{"id":"s14c20","front":"Hydrogen sulfide: nickname, smell and treatment?","back":"Sewer gas, rotten eggs (odor fades quickly). 100% O2; sodium nitrite 10 ml of 3% over 2 min (300 mg).","page":359,"deck":"s14"},{"id":"s14c21","front":"CO: symptom levels?","back":"Symptoms start at 10–20%; serious neuro/cardiac toxicity at 30–40%.","page":360,"deck":"s14"},{"id":"s14c22","front":"Methemoglobin formers: sources and clues?","back":"Aniline dyes, nitrites/nitrates, nitrobenzene. Chocolate-brown blood; SpO2 reads falsely low.","page":361,"deck":"s14"},{"id":"s14c23","front":"Ethylene glycol stages?","back":"1: CNS depression within 12 h. 2: cardiopulmonary within 48 h. 3: renal failure within 72 h.","page":362,"deck":"s14"},{"id":"s14c24","front":"Toxic alcohols: when is bicarb given?","back":"If respiratory rate is twice normal: 8.4% 1 mEq/kg.","page":362,"deck":"s14"},{"id":"s14c25","front":"Chloramine: how is it made?","back":"Mixing household bleach and ammonia; becomes hydrochloric acid in the airway.","page":363,"deck":"s14"},{"id":"s14c26","front":"Corrosive inhalation treatment?","back":"O2, albuterol 2.5 mg (1.25 mg under 1 yr), Solu-Medrol 125 mg, nebulized bicarb: 3 ml 8.4% adult, 3 ml 4.2% peds.","page":363,"deck":"s14"},{"id":"s14c27","front":"Phenol decon?","back":"Large volumes of water, then PEG 300; alternate soap/water and oil/PEG at least twice. Small water volumes increase absorption.","page":364,"deck":"s14"},{"id":"s15c01","front":"Who performs QA for the EMS system?","back":"The Medical Director: individual and system-based QA.","page":368,"deck":"s15"},{"id":"s15c02","front":"Six principles of QA?","back":"Build in quality; define expectations first; examine system and individual; positive reinforcement; expect but limit variation; collect data and adapt.","page":368,"deck":"s15"},{"id":"s15c03","front":"Multi-tier case review order?","back":"Station Captain, EMS Officer/Quality Supervisor, Medical Director, closed Quality meeting, then open meeting/training.","page":371,"deck":"s15"},{"id":"s15c04","front":"Station Captain's QA role?","back":"Reviews all charts for the 24-hour period (SOG E-128).","page":371,"deck":"s15"},{"id":"s15c05","front":"Quality Committee chair and co-chairs?","back":"Chair: Medical Director. Co-chairs: EMS Chief and President of the Union.","page":372,"deck":"s15"},{"id":"s15c06","front":"Is QA disciplinary?","back":"No: confidential, non-disciplinary, non-punitive; names removed during CQI.","page":373,"deck":"s15"},{"id":"s15c07","front":"Audit triggers?","back":"Protocol deviation, practice concern, advanced procedures, refusals, long response or scene times, unanticipated deaths, all ALERTS.","page":374,"deck":"s15"},{"id":"s15c08","front":"Sentinel event definition?","back":"(Joint Commission) an unanticipated event causing death or serious physical/psychological injury, not from the illness's natural course.","page":375,"deck":"s15"},{"id":"s15c09","front":"Sentinel event examples?","back":"Unrecognized failed airway, untreated symptomatic dysrhythmia, abandonment, med errors, equipment harm, drug diversion, assault on crew, MCI.","page":375,"deck":"s15"},{"id":"s15c10","front":"Who is notified immediately of a sentinel event?","back":"Battalion Chief, EMS Division Chief, Medical Director.","page":375,"deck":"s15"},{"id":"s15c11","front":"Just Culture test sequence?","back":"Appropriate care? Deliberate harm, health, standards, substitution, risky behavior, mitigating circumstances.","page":377,"deck":"s15"},{"id":"s15c12","front":"Four case dispositions?","back":"No-fault, Clinically Appropriate, Needs Improvement, Clinically Inappropriate.","page":378,"deck":"s15"},{"id":"s15c13","front":"Clinically Appropriate vs Needs Improvement?","back":"Both deviate. Appropriate: no substantial risk, maybe better outcome. Needs Improvement: potential risk of harm.","page":378,"deck":"s15"},{"id":"s15c14","front":"Where do Clinically Inappropriate cases go?","back":"Out of QA to Fire Rescue Administration for Administrative Action.","page":380,"deck":"s15"},{"id":"s15c15","front":"Coaching vs Clinical Improvement Plan?","back":"Coaching: first occurrence. CIP: more than one occurrence on the same/similar topic.","page":379,"deck":"s15"},{"id":"s15c16","front":"CIP must include?","back":"Objectives and process, a timeline, and feedback expectations.","page":379,"deck":"s15"},{"id":"s15c17","front":"If CIP expectations aren't met?","back":"Extend the timeframe, forward to Administration, or Medical Director may restrict credentialing.","page":379,"deck":"s15"},{"id":"s15c18","front":"EMS Action Items: how often and who communicates them?","back":"Quarterly training modules; Battalion Chiefs make sure crews get them.","page":381,"deck":"s15"},{"id":"s16c01","front":"2026: what's first-line for all intubations?","back":"Video laryngoscopy, to maximize first-pass success.","page":391,"deck":"s16"},{"id":"s16c02","front":"2026: procedural sedation change?","back":"Versed removed for procedural sedation; etomidate only.","page":391,"deck":"s16"},{"id":"s16c03","front":"2026: new cardiac protocols added?","back":"WPW protocol and ECMO alert for refractory VF.","page":391,"deck":"s16"},{"id":"s16c04","front":"2026: stable VT change?","back":"Amiodarone is contraindicated in pregnancy.","page":391,"deck":"s16"},{"id":"s16c05","front":"2026: termination of resuscitation change?","back":"Temperature over 90°F criterion added; TOR for trauma updated.","page":391,"deck":"s16"},{"id":"s16c06","front":"2026: post-ROSC hypotension options?","back":"Epi drip or push-dose epi; June update set post-ROSC MAP 65–70.","page":393,"deck":"s16"},{"id":"s16c07","front":"2026: trauma additions?","back":"Cefepime for open fractures, TXA protocol, dental injuries, Cyanokit link in burns.","page":391,"deck":"s16"},{"id":"s16c08","front":"2026: pain management changes?","back":"Fentanyl doses changed, Toradol added, ketamine dose decreased, ketamine for kids, peds IO lidocaine.","page":392,"deck":"s16"},{"id":"s16c09","front":"2026: new OB protocols?","back":"Shoulder dystocia, postpartum hemorrhage, neonatal resuscitation update, clonus defined, opening the amniotic sac.","page":392,"deck":"s16"},{"id":"s16c10","front":"2026: new procedures?","back":"SALAD, IO pain management, finger thoracostomy, meconium aspirator, intranasal, PEEP valve, pelvic splinting.","page":392,"deck":"s16"},{"id":"s16c11","front":"2026: decompression sickness and CO destination?","back":"Closest ED with a helipad.","page":391,"deck":"s16"},{"id":"s16c12","front":"2026: other new sections?","back":"FF rehab, emancipated minors, police custody, abdominal pain, behavioral emergencies, sickle cell, opioid addiction (future).","page":391,"deck":"s16"},{"id":"s16c13","front":"June 2026: NTG change?","back":"NTG paste is OK when CHF occurs with STEMI.","page":393,"deck":"s16"},{"id":"s16c14","front":"June 2026: med tool change?","back":"Med tool removed from the protocol; the app is primary.","page":393,"deck":"s16"}],"questions":[{"id":"s01q01","q":"How many paramedics must concur to deviate from protocol?","choices":["One with medical control","Two","Three","The EMS Officer alone"],"answer":1,"why":"Two concurring paramedics, with documentation and written notification.","page":27,"deck":"s01"},{"id":"s01q02","q":"Ventilation rate for a child WITH a pulse?","choices":["10/min","12/min","20/min","30/min"],"answer":2,"why":"Children: 20/min (1 every 3 sec) with a pulse; 10/min without.","page":32,"deck":"s01"},{"id":"s01q03","q":"Adult hypotension in these protocols is SBP under:","choices":["80","90","100","110"],"answer":2,"why":"Adult hypotension is defined as SBP under 100.","page":34,"deck":"s01"},{"id":"s01q04","q":"A 13-year-old with facial hair and underarm hair. Which protocols?","choices":["Pediatric","Adult","Medical control decides","Pediatric for drugs, adult for airway"],"answer":1,"why":"Once a child reaches puberty, adult EMS protocols apply.","page":34,"deck":"s01"},{"id":"s01q05","q":"STEMI 12-lead must be transmitted within:","choices":["5 minutes","10 minutes","15 minutes","20 minutes"],"answer":1,"why":"Obtained within 5 min of contact and transmitted within 10 min.","page":36,"deck":"s01"},{"id":"s01q06","q":"A valid Florida DNRO is on:","choices":["White paper","Yellow DH Form 1896","Any signed living will","A physician's phone order"],"answer":1,"why":"Original or yellow copy of DH Form 1896 with original signatures.","page":42,"deck":"s01"},{"id":"s01q07","q":"Daughter shows an unsigned photocopy of a DNRO for her pulseless father. Action?","choices":["Honor it","Begin resuscitation","Call LE","Ask the daughter to sign"],"answer":1,"why":"If there is any question about validity, resuscitation must begin.","page":42,"deck":"s01"},{"id":"s01q08","q":"Hypoglycemic patient wakes up after D10 and wants to refuse. Given Narcan earlier by PD. Can they refuse?","choices":["Yes, with capacity","No: Narcan was given","Yes if BGL over 100","Only with medical control"],"answer":1,"why":"Patients given Narcan for a suspected OD cannot refuse transport.","page":50,"deck":"s01"},{"id":"s01q09","q":"Who can sign a refusal for a 15-year-old when no parent is reachable and care can wait?","choices":["The 15-year-old","A teacher","A law enforcement officer","An adult sibling"],"answer":2,"why":"A parent/legal guardian or a law enforcement officer may sign.","page":51,"deck":"s01"},{"id":"s01q10","q":"Firefighter in rehab: HR 104, BP 150/90, temp 99.5. Return to work?","choices":["Yes","No: HR must be under 100","No: BP too high","Yes after fluids"],"answer":1,"why":"All criteria must be met; HR must be under 100.","page":59,"deck":"s01"},{"id":"s02q01","q":"Anaphylaxis with SBP 80. After IM epi, next?","choices":["Repeat IM epi in 5 min","Push-dose epi, IO recommended","Benadryl only","Albuterol"],"answer":1,"why":"Anaphylactic shock: IM epi then immediately push-dose epi; IO recommended.","page":65,"deck":"s02"},{"id":"s02q02","q":"Max single IM epi dose for a child in anaphylaxis?","choices":["0.15 mg","0.3 mg","0.5 mg","1 mg"],"answer":2,"why":"0.01 mg/kg, max single dose 0.5 mg.","page":66,"deck":"s02"},{"id":"s02q03","q":"Diabetic on glipizide, BGL 45 corrected to 110 with D10. Wants to stay home.","choices":["Release with sign-off","Transport regardless of glucose","Give oral glucose and release","Recheck in 15 min and release"],"answer":1,"why":"Patients on oral hypoglycemics are transported regardless of post-treatment glucose.","page":70,"deck":"s02"},{"id":"s02q04","q":"Hyperkalemia bundle: which drug goes first?","choices":["Sodium bicarb","Albuterol","Calcium chloride","Normal saline"],"answer":2,"why":"Calcium chloride 1 g over 2 min is given first.","page":74,"deck":"s02"},{"id":"s02q05","q":"Adult still seizing after two 5 mg Versed doses. Next?","choices":["Third Versed dose","Ketamine 100 mg","Etomidate 20 mg","Magnesium 2 g"],"answer":1,"why":"Add ketamine 100 mg after 2 Versed doses; be ready to manage the airway.","page":76,"deck":"s02"},{"id":"s02q06","q":"Which meets Sepsis Alert criteria?","choices":["UTI, SBP 130, RR 18, alert","Cellulitis, SBP 96, confused","Fever alone","Cough, RR 24, SBP 140, alert"],"answer":1,"why":"Suspected infection plus 2 of 3: SBP under 100 (or MAP under 65), AMS, RR over 22/EtCO2 under 25.","page":77,"deck":"s02"},{"id":"s02q07","q":"qSOFA-positive adult with SBP 128. Fluids?","choices":["None, BP is normal","500 ml","1 L regardless of BP","20 ml/kg"],"answer":2,"why":"1 L NS regardless of blood pressure.","page":78,"deck":"s02"},{"id":"s02q08","q":"Stroke patient with a left-sided deficit. Which RACE item do you test?","choices":["Aphasia","Neglect (agnosia)","Both","Neither"],"answer":1,"why":"Aphasia for right-sided deficits; neglect for left-sided deficits.","page":80,"deck":"s02"},{"id":"s02q09","q":"Patient woke up with stroke symptoms. Action?","choices":["Not a Stroke Alert: unknown onset","Stroke Alert to a Stroke Center","Closest ED","Call medical control"],"answer":1,"why":"Wake-up or unknown onset is transported to a Stroke Center as a Stroke Alert.","page":81,"deck":"s02"},{"id":"s03q01","q":"A COPD patient on BVM becomes hard to bag and hypotensive. First action?","choices":["Increase rate","Stop ventilating 20–40 seconds","Needle decompress","Give a fluid bolus"],"answer":1,"why":"Suspect auto-PEEP: stop positive pressure 20–40 seconds (10–20 peds) to allow full exhalation.","page":85,"deck":"s03"},{"id":"s03q02","q":"SpO2 target for an asthma patient?","choices":["88%","90%","94%","98%"],"answer":1,"why":"90% for COPD and asthma; 95% for others.","page":85,"deck":"s03"},{"id":"s03q03","q":"CPAP is contraindicated in which patient?","choices":["Moderate asthma","Pneumonia with distress","Lethargic COPD patient","CHF with SBP 150"],"answer":2,"why":"Decreased LOC (lethargic) and no spontaneous breathing are contraindications.","page":85,"deck":"s03"},{"id":"s03q04","q":"Adult severe asthma IM epi dose?","choices":["0.3 mg 1:1,000","0.5 mg 1:1,000","1 mg 1:10,000","0.01 mg/kg"],"answer":1,"why":"Epi 1:1,000 0.5 mg IM, may repeat 2x every 5 minutes.","page":86,"deck":"s03"},{"id":"s03q05","q":"Nebulized epi dose for croup?","choices":["0.5 ml","1 ml","3 ml of 1:1,000","3 ml of 1:10,000"],"answer":2,"why":"Epi 1:1,000, 3 ml (3 mg total) by nebulizer.","page":87,"deck":"s03"},{"id":"s03q06","q":"Child with suspected epiglottitis. Which is correct?","choices":["Place an OPA","Intubate early","BVM only if needed; no OPA/NPA or intubation","Inspect the throat"],"answer":2,"why":"Don't stress the child; no intubation, OPA or NPA. Ventilate by BVM as needed.","page":87,"deck":"s03"},{"id":"s03q07","q":"Max adult etomidate induction dose?","choices":["20 mg","30 mg","40 mg","0.15 mg/kg"],"answer":1,"why":"0.3 mg/kg, max 30 mg.","page":88,"deck":"s03"},{"id":"s03q08","q":"An 8-year-old can't be oxygenated with BVM or SGA. Surgical airway?","choices":["Surgical cric","Needle cric","Nasal intubation","Retrograde intubation"],"answer":1,"why":"Needle cricothyrotomy for children 10 and under.","page":88,"deck":"s03"},{"id":"s03q09","q":"In DSI, how long after induction is the paralytic given?","choices":["Immediately","About 1 minute","About 3 minutes","10 minutes"],"answer":2,"why":"Induction first, then about 3 minutes of support before the paralytic.","page":90,"deck":"s03"},{"id":"s03q10","q":"Ventilator default respiratory rate during cardiac arrest?","choices":["8","10","12","16"],"answer":1,"why":"CPR mode/PCV+: RR 10, PS 15, PEEP 5, FiO2 100%.","page":91,"deck":"s03"},{"id":"s03q11","q":"NIV peak pressure limit without an NG tube?","choices":["20 cm H2O","25 cm H2O","30 cm H2O","35 cm H2O"],"answer":1,"why":"Do not exceed 25 cm H2O unless an NG tube is in place.","page":92,"deck":"s03"},{"id":"s04q01","q":"A patient took two 81 mg aspirin this morning for chest pain. What aspirin do you give?","choices":["None","162 mg","324 mg","81 mg"],"answer":2,"why":"If less than 324 mg was taken in 24 hours, give the full 324 mg.","page":95,"deck":"s04"},{"id":"s04q02","q":"Which ST elevation meets STEMI criteria?","choices":["1 mm convex in V2 and V3","1.5 mm concave in II, III, aVF","1 mm convex in II, III, aVF","1 mm concave in V5 and V6"],"answer":2,"why":"Outside V2–V3, 1 mm convex/straight in 2 contiguous leads qualifies. Concave needs 2 mm.","page":96,"deck":"s04"},{"id":"s04q03","q":"Which is a STEMI disqualifier?","choices":["Inferior elevation","Reciprocal depression","Paced rhythm with QRS over 0.12","Elevation in V2–V3"],"answer":2,"why":"QRS over 0.12 (LBBB, pacemaker) is a STEMI mimic.","page":97,"deck":"s04"},{"id":"s04q04","q":"CHF patient with BP 84/50. Which treatment is contraindicated?","choices":["12-lead","CPAP","Advanced airway if LOC drops","Aspirin"],"answer":1,"why":"CPAP and NTG are contraindicated with SBP under 90.","page":98,"deck":"s04"},{"id":"s04q05","q":"Lasix dose for CHF?","choices":["20 mg","40 mg","80 mg","1 mg/kg"],"answer":1,"why":"Lasix 40 mg IV, one dose.","page":98,"deck":"s04"},{"id":"s04q06","q":"LVAD patient in arrest with a working pump option available. Compressions?","choices":["Mechanical CPR","Manual CPR immediately","Only if no hand pump, pump not working and no way to restart it","Never"],"answer":2,"why":"Compress only when the VAD has no hand pump, isn't working, and nothing else restarts it. Never mechanical CPR.","page":101,"deck":"s04"},{"id":"s04q07","q":"Max adult atropine for bradycardia?","choices":["1 mg","2 mg","3 mg","0.04 mg/kg"],"answer":2,"why":"1 mg every 3–5 min, max 3 mg.","page":102,"deck":"s04"},{"id":"s04q08","q":"Hypotensive brady with third-degree block. First treatment?","choices":["Atropine 1 mg","1 L NS","Transcutaneous pacing","Push-dose epi"],"answer":2,"why":"High-degree AV block with hypotension, or chest pain: go directly to pacing.","page":102,"deck":"s04"},{"id":"s04q09","q":"Rapid A-fib, BP 130/80, rate 160. First Cardizem dose?","choices":["5 mg","10 mg over 2 min","15 mg over 2 min","0.25 mg/kg"],"answer":1,"why":"10 mg over 2 min; 15 mg if HR still over 120 after 5 min.","page":104,"deck":"s04"},{"id":"s04q10","q":"Unstable rapid A-fib, SBP 76. Correct statement?","choices":["Cardiovert at 150 J","1 L NS then calcium chloride 1 g","Adenosine 12 mg","Amiodarone 150 mg"],"answer":1,"why":"Do not cardiovert A-fib. Give fluid and calcium; Cardizem only if SBP rises over 80.","page":104,"deck":"s04"},{"id":"s04q11","q":"First synchronized cardioversion on the LifePak for unstable SVT?","choices":["150 J","200 J","300 J","360 J"],"answer":2,"why":"LifePak 300 J then 360 J. Zoll 150 J then 200 J.","page":105,"deck":"s04"},{"id":"s04q12","q":"20 kg child in stable SVT. First adenosine dose?","choices":["1 mg","2 mg","4 mg","6 mg"],"answer":1,"why":"0.1 mg/kg = 2 mg (max 6 mg).","page":107,"deck":"s04"},{"id":"s04q13","q":"Known WPW patient with a rapid regular tachycardia, stable. Treatment?","choices":["Adenosine","Cardizem","Monitor and transport","Amiodarone 150 mg"],"answer":2,"why":"Stable WPW: monitor and transport. No adenosine or Cardizem.","page":108,"deck":"s04"},{"id":"s04q14","q":"Dialysis patient, QRS 240 ms, rate 105. What do you NOT give?","choices":["Calcium chloride","Sodium bicarbonate","Amiodarone","500 ml NS"],"answer":2,"why":"Really wide complex tachycardia is likely hyperkalemia: never amiodarone.","page":109,"deck":"s04"},{"id":"s04q15","q":"Stable VT in a pregnant patient. Antiarrhythmic?","choices":["Amiodarone 150 mg","Lidocaine 100 mg","Adenosine 12 mg","Magnesium 2 g"],"answer":1,"why":"Amiodarone is contraindicated in pregnancy; use lidocaine.","page":111,"deck":"s04"},{"id":"s04q16","q":"Which favors VT over SVT with aberrancy?","choices":["Normal R-wave progression","Irregularly irregular rhythm","Precordial concordance","Slight QRS widening"],"answer":2,"why":"Concordance, capture/fusion beats, no RS, and R-to-S over 100 ms favor VT.","page":110,"deck":"s04"},{"id":"s05q01","q":"An adult in asystole has been worked for 22 minutes, EtCO2 is 8, H's and T's addressed, temp 97°F. The arrest was witnessed. What do you do?","choices":["Terminate on scene with BC approval","Transport; witnessed arrests must be transported","Continue on scene 10 more minutes","Terminate without BC approval"],"answer":1,"why":"All witnessed cardiac arrest patients must be transported.","page":117,"deck":"s05"},{"id":"s05q02","q":"Which is a CONCLUSIVE sign for not starting resuscitation?","choices":["Pupils fixed and dilated","Asystole","Rigor mortis","Downtime over 20 minutes"],"answer":2,"why":"Rigor mortis is conclusive. The others are presumptive and all must be present together.","page":117,"deck":"s05"},{"id":"s05q03","q":"How many compressions make up one high-performance CPR cycle?","choices":["200 in 2 minutes","220 in 2 minutes","240 in 2 minutes","30:2 for 5 cycles"],"answer":1,"why":"Cycles are 220 compressions in two minutes.","page":118,"deck":"s05"},{"id":"s05q04","q":"How is the adult epi drip mixed for PEA/asystole?","choices":["1 mg in 250 ml, 60-drop set","2 mg in 100 ml, 10-drop set, 1 drop/sec","4 mg in 250 ml, 10-drop set","2 mg in 500 ml, wide open"],"answer":1,"why":"2 mg in 100 ml NS, 10-drop set, 1 drop per second over about 16 minutes. Never more than 2 mg in any bag.","page":118,"deck":"s05"},{"id":"s05q05","q":"What is the second amiodarone dose in VF arrest?","choices":["300 mg","150 mg","100 mg","1 mg/kg"],"answer":1,"why":"300 mg first, then 150 mg IV/IO push.","page":118,"deck":"s05"},{"id":"s05q06","q":"Amiodarone is unavailable. Lidocaine dose for an adult in VF?","choices":["1 mg/kg, max 100 mg, repeat once in 5 min","1.5 mg/kg, repeat every 3 min","100 mg, repeat every 3 min to 3 mg/kg","0.5 mg/kg once"],"answer":0,"why":"1 mg/kg IV/IO push, max 100 mg, repeated once after 5 minutes if no effect.","page":118,"deck":"s05"},{"id":"s05q07","q":"When is the mechanical CPR device applied?","choices":["Immediately on arrival","After 1 round of 220","After a minimum of 3 rounds of 220","Only for transport"],"answer":2,"why":"After at least 3 rounds (about 6 minutes), with discretion for small or frail patients.","page":118,"deck":"s05"},{"id":"s05q08","q":"A patient in TCA overdose goes into arrest. Which reversal agent is listed in the T's?","choices":["Glucagon","Calcium chloride","Sodium bicarbonate","Narcan"],"answer":2,"why":"TCA: sodium bicarb. Beta blocker: glucagon. CCB: calcium chloride. Opiates: Narcan.","page":119,"deck":"s05"},{"id":"s05q09","q":"Second pediatric defibrillation in VF?","choices":["2 J/kg","4 J/kg","10 J/kg","200 J"],"answer":1,"why":"2 J/kg first, then 4 J/kg, then 10 J/kg or max.","page":121,"deck":"s05"},{"id":"s05q10","q":"Which patient qualifies for an ECMO alert?","choices":["Age 70, witnessed VF, CPR in 3 min","Age 50, unwitnessed asystole","Age 45, witnessed VF, CPR in 4 min, 15 min transport","Age 55, witnessed VF, 35 min transport"],"answer":2,"why":"Under 65, witnessed, CPR within 5 min, shockable, and under 20 miles / 30 min transport.","page":122,"deck":"s05"},{"id":"s05q11","q":"Where are refractory VF ECMO alerts transported?","choices":["Closest STEMI center","Broward Health Medical Center","Memorial Regional","Closest ED"],"answer":2,"why":"Memorial Regional is currently the only Broward hospital that can take refractory VF ECMO alerts.","page":122,"deck":"s05"},{"id":"s05q12","q":"A patient regains consciousness during CPR without a pulse. Treatment?","choices":["Versed 2.5 mg","Ketamine 1 mg/kg","Etomidate 10 mg slow push","Stop compressions"],"answer":2,"why":"Etomidate 10 mg slow IV/IO push, may repeat once prn.","page":124,"deck":"s05"},{"id":"s05q13","q":"Adult post-ROSC: what is the SBP goal?","choices":["90 mmHg","100 mmHg","110 mmHg","120 mmHg"],"answer":1,"why":"Manage rate, rhythm, then BP with a goal SBP of 100 mmHg, then 12-lead.","page":125,"deck":"s05"},{"id":"s05q14","q":"Patient converts from VF on the first shock with no amiodarone given. Post-ROSC antiarrhythmic?","choices":["Amio 150 mg infusion","Amio 300 mg bolus","None","Lidocaine 1 mg/kg"],"answer":2,"why":"If the patient converts after the initial defibrillation, no antiarrhythmic is given.","page":125,"deck":"s05"},{"id":"s05q15","q":"Minimum SBP for a 6-year-old?","choices":["70 mmHg","76 mmHg","82 mmHg","90 mmHg"],"answer":2,"why":"Ages 1–10: 70 + (2 × age) = 70 + 12 = 82 mmHg.","page":126,"deck":"s05"},{"id":"s05q16","q":"In a 3-person Pit Crew, who starts the epi drip?","choices":["Position 1","Position 2","Position 3","Whoever is free"],"answer":1,"why":"Position 2 connects the monitor, preps the EZ-IO, defibrillates, resumes CPR and starts the epi drip.","page":129,"deck":"s05"},{"id":"s06q01","q":"START triage: adult breathing 34/min. Tag?","choices":["Green","Yellow","Red","Black"],"answer":2,"why":"Respiratory rate over 30 is RED.","page":136,"deck":"s06"},{"id":"s06q02","q":"START triage: radial pulse present, follows commands, can't walk due to femur fracture. Tag?","choices":["Green","Yellow","Red","Black"],"answer":1,"why":"On the START chart, a non-walking patient who passes RPM is DELAYED (yellow); injuries like fractures can also call for YELLOW.","page":139,"deck":"s06"},{"id":"s06q03","q":"JumpSTART: apneic 5-year-old with a pulse after airway opening. Next step?","choices":["Tag black","Give 5 rescue breaths","Tag red","Move on"],"answer":1,"why":"If there's a pulse, give 5 rescue breaths; still apneic = BLACK, breathing = RED.","page":137,"deck":"s06"},{"id":"s06q04","q":"An MCI with 25 patients is which level?","choices":["Level I","Level II","Level III","Level IV"],"answer":2,"why":"Level III is 21–100.","page":133,"deck":"s06"},{"id":"s06q05","q":"Which single finding makes a 10-year-old a pediatric trauma alert?","choices":["Single closed femur fracture","SBP 95","Open tibia fracture","Brief loss of consciousness"],"answer":2,"why":"An open long-bone fracture is a RED criterion. The others are BLUE and need two.","page":143,"deck":"s06"},{"id":"s06q06","q":"A 70-year-old on Eliquis falls from standing. Trauma category?","choices":["Not a trauma patient","High-index (Level II) trauma","Trauma alert","Paramedic judgment only"],"answer":1,"why":"A fall from any height in an adult over 55 on an anticoagulant meets high-index criteria.","page":145,"deck":"s06"},{"id":"s06q07","q":"Adult with 20% 2nd-degree burns. Fluid?","choices":["None","500 ml NS","1 L NS","20 ml/kg"],"answer":2,"why":"2nd-degree over 15% or 3rd-degree over 5%: burn sheet and 1 L NS.","page":147,"deck":"s06"},{"id":"s06q08","q":"Severe TBI (GCS 7) with hemorrhage. SBP target?","choices":["80–90","90–100","110–120","Permissive hypotension"],"answer":2,"why":"Maintain SBP 110–120 even with penetrating trauma and hemorrhage.","page":150,"deck":"s06"},{"id":"s06q09","q":"Signs of herniation. EtCO2 target?","choices":["25 mmHg","30 mmHg","35 mmHg","40 mmHg"],"answer":2,"why":"Mild hyperventilation to keep EtCO2 at 35 mmHg.","page":150,"deck":"s06"},{"id":"s06q10","q":"Preferred needle decompression site?","choices":["5th ICS midaxillary","2nd or 3rd ICS midclavicular","4th ICS anterior axillary","3rd ICS midaxillary"],"answer":1,"why":"Anterior approach, 2nd or 3rd ICS midclavicular. Finger thoracostomy is 3rd ICS midaxillary.","page":156,"deck":"s06"},{"id":"s06q11","q":"Crush injury: which fluid should be avoided?","choices":["Normal saline","Lactated Ringer's","Whole blood","None"],"answer":1,"why":"Avoid potassium-containing fluids like LR.","page":157,"deck":"s06"},{"id":"s06q12","q":"A traction splint is OK for:","choices":["Mid-shaft femur with suspected pelvic fracture","Open mid-shaft femur, no visible bone","Femur fracture with hip fracture","Distal femur fracture"],"answer":1,"why":"Open fractures with no visible bone may be splinted; the others are exclusions.","page":163,"deck":"s06"},{"id":"s06q13","q":"Open tib/fib fracture in a 35-year-old. Antibiotic?","choices":["Cefepime 1 g","Cefepime 2 g over about 16 min","Ceftriaxone 1 g","None prehospital"],"answer":1,"why":"Cefepime 2 g in 100 ml, 1 drop/sec on a 10-drop set, adults only.","page":162,"deck":"s06"},{"id":"s06q14","q":"Pregnant trauma patient needing SMR. Positioning?","choices":["Flat supine","Left lateral recumbent","4–6 inches of padding under the right side","Trendelenburg"],"answer":2,"why":"Pad under the right side while keeping alignment.","page":164,"deck":"s06"},{"id":"s07q01","q":"Trauma patient apneic and pulseless, but pupils are reactive. Action?","choices":["Do not resuscitate","Resuscitate on scene 20 minutes","Resuscitate en route to the trauma center","Apply mechanical CPR and transport"],"answer":2,"why":"All three signs must be present to withhold. Otherwise resuscitate en route; never mechanical CPR in trauma.","page":170,"deck":"s07"},{"id":"s07q02","q":"Neurogenic shock is suggested by:","choices":["Cool clammy skin and tachycardia","Warm dry skin, hypotension and bradycardia","Hypertension and bradycardia","Tachycardia and wide pulse pressure"],"answer":1,"why":"Warm/dry skin, hypotension with bradycardia, injury above T6.","page":171,"deck":"s07"},{"id":"s07q03","q":"HR 120, SBP 85 after a stabbing. Whole blood indicated?","choices":["No, SBP is over 70","Yes, SBP under 90 with HR 110+","Only if over 65","Only with medical control"],"answer":1,"why":"SBP under 90 with HR 110 or more is an indication.","page":175,"deck":"s07"},{"id":"s07q04","q":"Shock index for HR 120 and SBP 100?","choices":["0.83, mild","1.2, moderate","1.0, moderate","1.4, severe"],"answer":1,"why":"120 ÷ 100 = 1.2, moderate shock (1.0 to under 1.4).","page":175,"deck":"s07"},{"id":"s07q05","q":"Whole blood dose for a 9-year-old with no signs of puberty?","choices":["1 unit","10 ml/kg","15 ml/kg","20 ml/kg"],"answer":2,"why":"Pediatrics over 5 with no puberty: 15 ml/kg.","page":174,"deck":"s07"},{"id":"s07q06","q":"Max time whole blood may stay in the field cooler?","choices":["8 hours","12 hours","24 hours","72 hours"],"answer":2,"why":"Routine 12 hours, maximum 24 hours.","page":177,"deck":"s07"},{"id":"s07q07","q":"TXA is contraindicated when the injury occurred:","choices":["1 hour ago","2 hours ago","Over 3 hours ago","In a patient over 65"],"answer":2,"why":"Injuries greater than 3 hours old are a contraindication.","page":179,"deck":"s07"},{"id":"s07q08","q":"Adult TXA administration?","choices":["1 g over 10 min","2 g in 100 ml over about 5 min","2 g IV push","15 mg/kg over 16 min"],"answer":1,"why":"2 g in 100 ml, 10-drop set at 3 drops per second (about 5 minutes).","page":179,"deck":"s07"},{"id":"s08q01","q":"Max adult glucagon dose for beta blocker OD?","choices":["1 mg","5 mg","10 mg","No max"],"answer":2,"why":"1 mg/min for refractory hypotension, max 10 mg.","page":184,"deck":"s08"},{"id":"s08q02","q":"Amlodipine overdose with SBP 82. After 1 L NS?","choices":["Glucagon 1 mg","Calcium chloride 1 g slow","Sodium bicarb 50 mEq","Atropine 1 mg"],"answer":1,"why":"CCB OD: calcium chloride 1 g slow IV/IO over 2 min.","page":185,"deck":"s08"},{"id":"s08q03","q":"Agitated cocaine patient, 100 kg. Ketamine IM dose?","choices":["200 mg","400 mg","500 mg","800 mg"],"answer":1,"why":"4 mg/kg IM, max single dose 400 mg (total 800 mg).","page":186,"deck":"s08"},{"id":"s08q04","q":"Adult TCA overdose: QRS threshold for bicarb?","choices":["Over 0.08 sec","Over 0.10 sec","Over 0.12 sec","Over 0.20 sec"],"answer":1,"why":"Over 0.10 seconds (2.5 small boxes) in adults; 0.08 in children.","page":187,"deck":"s08"},{"id":"s08q05","q":"Maximum sodium bicarb in adult TCA overdose?","choices":["50 mEq","100 mEq","150 mEq","1 mEq/kg"],"answer":2,"why":"50 mEq every 5 minutes, max 150 mEq.","page":187,"deck":"s08"},{"id":"s08q06","q":"Adult opioid OD: Narcan is repeated for RR under:","choices":["8","10","12","16"],"answer":2,"why":"Repeat every minute prn for RR under 12, up to 10 mg.","page":189,"deck":"s08"},{"id":"s09q01","q":"How often is a restrained patient reassessed?","choices":["Every 3 minutes","Every 5 minutes","Every 10 minutes","On arrival only"],"answer":0,"why":"After application and every 3 minutes after.","page":195,"deck":"s09"},{"id":"s09q02","q":"Which restraint can FLFR personnel apply?","choices":["Flex cuffs","Handcuffs","Soft restraints","Hobble restraint"],"answer":2,"why":"Hard ties or anything requiring a key are law enforcement only.","page":194,"deck":"s09"},{"id":"s09q03","q":"Max total ketamine for an adult in chemical restraint?","choices":["400 mg","600 mg","800 mg","4 mg/kg"],"answer":2,"why":"4 mg/kg IM, max single dose 400 mg and total 800 mg.","page":196,"deck":"s09"},{"id":"s09q04","q":"Patient drooling heavily after ketamine. Treatment?","choices":["Suction only","Atropine 1 mg","Narcan 2 mg","Versed 2.5 mg"],"answer":1,"why":"Hypersalivation: atropine 1 mg IV/IM/IO.","page":197,"deck":"s09"},{"id":"s09q05","q":"Adult ketamine max total for pain?","choices":["25 mg","50 mg","75 mg","100 mg"],"answer":2,"why":"25 mg, repeat 2x every 5 min, max 75 mg.","page":198,"deck":"s09"},{"id":"s09q06","q":"Toradol is appropriate for:","choices":["17-year-old ankle injury","Kidney stone in a 40-year-old","Suspected cardiac chest pain","TBI with headache"],"answer":1,"why":"Excellent for kidney stones and musculoskeletal injury; not under 18, cardiac pain or TBI.","page":198,"deck":"s09"},{"id":"s09q07","q":"A woman at 36 weeks in active labor requests pain meds for contractions.","choices":["Fentanyl 50 mcg","Ketamine 25 mg","Not treated: labor pain","Toradol 15 mg"],"answer":2,"why":"Pain meds aren't given for labor pain at 32+ weeks in active labor.","page":198,"deck":"s09"},{"id":"s10q01","q":"Suspected decompression sickness, not in arrest. Destination?","choices":["Closest ED","Nearest ED with a helipad","Any trauma center","Hyperbaric chamber directly by ground"],"answer":1,"why":"Transport to the nearest ED with a helipad; helipad use is excluded from EMTALA.","page":205,"deck":"s10"},{"id":"s10q02","q":"Drowning victim in arrest, temperature 88°F. Pronounce on scene?","choices":["Yes","No, temperature must be over 90°F","Yes with BC approval","Only if asystolic"],"answer":1,"why":"Pronounce only if the temperature is over 90°F (32°C).","page":206,"deck":"s10"},{"id":"s10q03","q":"Heat stroke, temp 105°F. Which is correct?","choices":["Ice water immersion","Ice packs to axilla and groin, chilled NS, mist and fan","Cool until shivering","Oral fluids only"],"answer":1,"why":"Rapid cooling over 103°F; don't cool to the point of shivering.","page":208,"deck":"s10"},{"id":"s10q04","q":"Man-of-war sting. Rinse with:","choices":["Fresh water","Sterile water","Sea water","Vinegar only"],"answer":2,"why":"Rinse with sea water; no fresh or sterile water, ice or rubbing.","page":211,"deck":"s10"},{"id":"s10q05","q":"Pregnant patient with CO exposure, SpCO 4%, no symptoms.","choices":["Release","Strong hyperbaric consideration","Only if symptomatic","Only if SpCO over 10%"],"answer":1,"why":"Pediatric and OB patients with confirmed exposure get strong hyperbaric consideration regardless of level.","page":212,"deck":"s10"},{"id":"s10q06","q":"Max total Cyanokit dose for an adult?","choices":["5 g","7.5 g","10 g","70 mg/kg"],"answer":2,"why":"5 g over 10–15 min, may repeat once for 10 g total.","page":213,"deck":"s10"},{"id":"s11q01","q":"Patient 26 weeks pregnant with abdominal pain. Destination?","choices":["Closest ED","Closest OB hospital","Hospital of choice","Trauma center"],"answer":1,"why":"Over 20 weeks with abdominal/pelvic pain goes to the closest OB hospital.","page":216,"deck":"s11"},{"id":"s11q02","q":"Painless bright red bleeding at 34 weeks suggests:","choices":["Abruptio placentae","Placenta previa","Uterine rupture","Ectopic"],"answer":1,"why":"Previa is painless bright red bleeding; abruptio is painful with dark blood.","page":218,"deck":"s11"},{"id":"s11q03","q":"Actively seizing eclamptic with IV access. Magnesium?","choices":["2 g IV only","4 g IV wide open and 2 g IM","6 g IM only","4 g IV over 20 min"],"answer":1,"why":"Bundle: mag 4 g IV/IO wide open and 2 g IM (6 g IM in 3 sites if no access).","page":219,"deck":"s11"},{"id":"s11q04","q":"First umbilical clamp distance from the newborn?","choices":["2 inches","4 inches","6 inches","8 inches"],"answer":2,"why":"First clamp 6 inches from the newborn; second 2 inches further toward the mother.","page":220,"deck":"s11"},{"id":"s11q05","q":"Shoulder dystocia: which is contraindicated?","choices":["McRoberts maneuver","Suprapubic pressure","Fundal pressure","Telling mom not to push"],"answer":2,"why":"Never apply fundal pressure; it can worsen impaction or rupture the uterus.","page":223,"deck":"s11"},{"id":"s11q06","q":"Prolapsed cord with a strong pulse. Do you still push the baby off the cord?","choices":["No, only if pulseless","Yes, regardless of pulse","Only during contractions","Only en route"],"answer":1,"why":"Push the baby up off the cord regardless of whether a pulse is present.","page":225,"deck":"s11"},{"id":"s11q07","q":"Pitocin dose for postpartum hemorrhage?","choices":["5 units IV","10 units IM","10 units IV push","20 units in 1 L"],"answer":1,"why":"10 units IM in the lateral thigh, one dose.","page":226,"deck":"s11"},{"id":"s11q08","q":"Newborn HR 50 after 30 seconds of PPV. Next?","choices":["Continue PPV only","Chest compressions with PPV at 3:1","Epi immediately","Intubate first"],"answer":1,"why":"HR under 60: PPV plus compressions at 3:1; epi if HR stays under 60.","page":227,"deck":"s11"},{"id":"s12q01","q":"Inferior ST elevation on the 12-lead. Additional lead?","choices":["V7","V4R","V8","aVR"],"answer":1,"why":"Run a V4R when ST changes are seen in II, III or aVF.","page":234,"deck":"s12"},{"id":"s12q02","q":"Glucometer reads 'HI'. BGL is:","choices":["Over 300","Over 400","Over 500","Over 600"],"answer":2,"why":"HI means over 500; KETONES means over 300.","page":238,"deck":"s12"},{"id":"s12q03","q":"Bougie advances freely with no clicks. Where is it?","choices":["Trachea","Right mainstem","Esophagus","Vallecula"],"answer":2,"why":"No resistance and no clicking means the esophagus.","page":242,"deck":"s12"},{"id":"s12q04","q":"Which is an absolute CPAP contraindication?","choices":["Nausea","Hypovolemia","Patient under 30 kg","Recent gastric surgery"],"answer":2,"why":"Under 30 kg is absolute; the others are relative.","page":244,"deck":"s12"},{"id":"s12q05","q":"Failed airway in a 9-year-old. Surgical option?","choices":["Surgical cric","Needle cric","Retrograde","Nasotracheal"],"answer":1,"why":"Needle cric for 10 and under; surgical cric is contraindicated.","page":248,"deck":"s12"},{"id":"s12q06","q":"i-gel size for a 70 kg adult?","choices":["3","4","5","2.5"],"answer":1,"why":"Size 4 is 50–90 kg.","page":251,"deck":"s12"},{"id":"s12q07","q":"Which patient can receive a nasotracheal intubation?","choices":["Apneic adult","Suspected basilar skull fracture","Breathing adult with intact airway anatomy","8-year-old breathing child"],"answer":2,"why":"Requires spontaneous breathing and puberty; no basilar skull fracture or apnea.","page":250,"deck":"s12"},{"id":"s12q08","q":"Max meconium suction pressure?","choices":["80 mmHg","100 mmHg","150 mmHg","200 mmHg"],"answer":1,"why":"No higher than 100 mmHg, no more than 5 seconds at a time.","page":259,"deck":"s12"},{"id":"s12q09","q":"Preferred IO site in an infant?","choices":["Proximal humerus","Proximal tibia","Distal femur","Sternum"],"answer":2,"why":"Distal femur is preferred in infants and small children.","page":267,"deck":"s12"},{"id":"s12q10","q":"IO needle for a 45 kg adult humerus?","choices":["15 mm pink","25 mm blue","45 mm yellow","Any"],"answer":2,"why":"45 mm for 40 kg+ and for humerus/femur in adults; 25 mm for adult tibia.","page":266,"deck":"s12"},{"id":"s12q11","q":"Tourniquet is on and the limb is still bleeding.","choices":["Tighten until it breaks","Remove and reapply distal","Add a second tourniquet proximal","Pack the wound only"],"answer":2,"why":"Place a second tourniquet proximal to the first.","page":286,"deck":"s12"},{"id":"s12q12","q":"Pelvic binder should be centered over the:","choices":["Iliac crests","Umbilicus","Greater trochanters","Mid-thigh"],"answer":2,"why":"Center over the greater trochanters, not the iliac crests or abdomen.","page":280,"deck":"s12"},{"id":"s13q01","q":"Push-dose epi is how many mcg per ml?","choices":["1 mcg/ml","10 mcg/ml","100 mcg/ml","0.1 mg/ml"],"answer":1,"why":"9 ml NS + 1 ml of 1:10,000 makes 1:100,000, or 10 mcg/ml.","page":293,"deck":"s13"},{"id":"s13q02","q":"Maximum total push-dose epi?","choices":["0.1 mg","0.3 mg","0.5 mg","1 mg"],"answer":1,"why":"1 ml every 30 seconds, may repeat 2x, max total dose 0.3 mg.","page":293,"deck":"s13"},{"id":"s13q03","q":"Which patient should NOT get adenosine?","choices":["SVT at 180 with asthma history","SVT on carbamazepine (Tegretol)","SVT at 160 in a 40-year-old","SVT after failed Valsalva"],"answer":1,"why":"Carbamazepine is a listed contraindication. Asthma/COPD is a precaution.","page":297,"deck":"s13"},{"id":"s13q04","q":"Amiodarone is contraindicated in which rhythm?","choices":["Stable VT","Pulseless VT","Torsades de pointes","VF"],"answer":2,"why":"Torsades is a listed contraindication; it is treated with magnesium.","page":299,"deck":"s13"},{"id":"s13q05","q":"Smallest adult atropine dose allowed?","choices":["0.1 mg","0.25 mg","0.5 mg","1 mg"],"answer":2,"why":"Don't give less than 0.5 mg to an adult or 0.1 mg to a child.","page":301,"deck":"s13"},{"id":"s13q06","q":"A patient becomes hypotensive after Cardizem. Treatment?","choices":["Push-dose epi","Calcium chloride 500 mg and 500 ml NS","Glucagon 1 mg","Atropine 1 mg"],"answer":1,"why":"Give 500 mg calcium chloride and 500 ml NS.","page":304,"deck":"s13"},{"id":"s13q07","q":"Who carries the Cyanokit?","choices":["Every rescue","Engine companies","EMS Supervisor and HazMat units","Battalion Chiefs only"],"answer":2,"why":"It is carried on EMS Supervisor and HazMat units only.","page":306,"deck":"s13"},{"id":"s13q08","q":"Epinephrine is contraindicated in which condition?","choices":["Anaphylaxis","Hypovolemic shock","Asthma","Bradycardia"],"answer":1,"why":"Hypovolemic shock is the listed contraindication.","page":309,"deck":"s13"},{"id":"s13q09","q":"100 mcg of fentanyl is roughly equal to how much morphine?","choices":["1 mg","5 mg","10 mg","20 mg"],"answer":2,"why":"About 10 mg of morphine.","page":311,"deck":"s13"},{"id":"s13q10","q":"Ketamine is contraindicated in which patient?","choices":["Head injury","Penetrating eye injury","Hypertension","Asthma"],"answer":1,"why":"Listed contraindications are allergy and penetrating eye injury.","page":314,"deck":"s13"},{"id":"s13q11","q":"Labetalol may be used for which condition in these protocols?","choices":["Hypertensive stroke","Aortic dissection","Severe pre-eclampsia/eclampsia","Rapid A-fib"],"answer":2,"why":"EMS use is for pre-eclampsia in pregnancy ONLY: 20 mg IV/IO over 2 min.","page":317,"deck":"s13"},{"id":"s13q12","q":"Narcan should be titrated to what endpoint?","choices":["Full alertness","Pupil dilation","Adequate respiratory drive","Normal heart rate"],"answer":2,"why":"Titrate to adequate respiratory drive using EtCO2 and SpO2.","page":320,"deck":"s13"},{"id":"s13q13","q":"A patient took Cialis 36 hours ago and is in pulmonary edema. NTG paste?","choices":["Yes, half dose","Yes, full dose","No: Cialis within 48 hours","Only with IV access"],"answer":2,"why":"Contraindicated with Cialis within 48 hours (sildenafil/Levitra within 24).","page":322,"deck":"s13"},{"id":"s13q14","q":"Oxytocin can be given when:","choices":["Baby delivered, placenta not yet","Baby and placenta delivered, bleeding despite massage","Before delivery to speed labor","For a breech delivery"],"answer":1,"why":"Only after all fetus and placenta are delivered and bleeding persists despite massage and nursing.","page":327,"deck":"s13"},{"id":"s13q15","q":"Toradol minimum age?","choices":["12","16","18","No limit"],"answer":2,"why":"Do not give to patients under 18.","page":332,"deck":"s13"},{"id":"s13q16","q":"Zofran is contraindicated with QTc over:","choices":["440 ms","460 ms","480 ms","500 ms"],"answer":3,"why":"Prolonged QTc over 500 ms is a contraindication.","page":334,"deck":"s13"},{"id":"s13q17","q":"Pediatric D10 dose?","choices":["2 ml/kg","5 ml/kg","10 ml/kg","20 ml/kg"],"answer":1,"why":"The med tool lists D10 at 5 ml/kg IV/IO.","page":336,"deck":"s13"},{"id":"s14q01","q":"Severe organophosphate poisoning (apnea, massive secretions). Initial adult atropine?","choices":["1 mg","2 mg","4 mg","6 mg"],"answer":3,"why":"2 mg mild, 4 mg moderate, 6 mg severe; repeat every 5 min, no max.","page":353,"deck":"s14"},{"id":"s14q02","q":"2-PAM should NOT be used in:","choices":["Sarin","VX","Known carbamate poisoning","Parathion"],"answer":2,"why":"Pralidoxime is not used in known carbamate poisonings.","page":353,"deck":"s14"},{"id":"s14q03","q":"HF burn with severe pain and normal-looking skin. Treat pain with:","choices":["Fentanyl","Ketamine","Calcium gluconate","Ice"],"answer":2,"why":"Pain is an indication for calcium, not analgesics.","page":354,"deck":"s14"},{"id":"s14q04","q":"Chocolate-brown blood and a falsely low SpO2 suggest:","choices":["Cyanide","CO","Methemoglobinemia","Hydrogen sulfide"],"answer":2,"why":"Methemoglobin formers turn blood chocolate brown and read falsely low on pulse ox.","page":361,"deck":"s14"},{"id":"s14q05","q":"Rotten-egg odor at a sewer and an unconscious worker. Antidote?","choices":["Cyanokit","Sodium nitrite","Atropine","Calcium gluconate"],"answer":1,"why":"Hydrogen sulfide: 100% O2 and sodium nitrite 10 ml of 3%.","page":359,"deck":"s14"},{"id":"s14q06","q":"Removing clothing removes how much contamination?","choices":["20–30%","50%","80–90%","100%"],"answer":2,"why":"Clothing removal removes 80–90% of the contaminant.","page":350,"deck":"s14"},{"id":"s15q01","q":"Who chairs the Quality Committee?","choices":["EMS Chief","Fire Chief","Medical Director","Union President"],"answer":2,"why":"Medical Director chairs; EMS Chief and Union President co-chair.","page":372,"deck":"s15"},{"id":"s15q02","q":"Deviation from protocol with potential risk of harm. Disposition?","choices":["No-fault","Clinically appropriate","Needs improvement","Clinically inappropriate"],"answer":2,"why":"Needs Improvement: deviation that may have posed potential risk.","page":378,"deck":"s15"},{"id":"s15q03","q":"A medic's first QA finding on a topic results in:","choices":["CIP","Coaching","Administrative action","Credential restriction"],"answer":1,"why":"Coaching on first occurrence; CIP for repeat occurrences.","page":379,"deck":"s15"},{"id":"s15q04","q":"Which is a sentinel event?","choices":["Extended scene time","A refusal","Unrecognized failed airway","An ALERT patient"],"answer":2,"why":"Unrecognized failed airway is a listed sentinel event; the others are audit triggers.","page":375,"deck":"s15"},{"id":"s15q05","q":"Who communicates quarterly EMS Action Items to crews?","choices":["Station Captains","Battalion Chiefs","EMS Captains","Medical Director"],"answer":1,"why":"Battalion Chiefs are responsible for communicating them.","page":381,"deck":"s15"},{"id":"s16q01","q":"Under 2026 protocols, sedation for cardioversion/pacing is:","choices":["Versed","Etomidate only","Ketamine","Fentanyl"],"answer":1,"why":"Versed was removed for procedural sedation; etomidate only.","page":391,"deck":"s16"},{"id":"s16q02","q":"Which was added in 2026 for refractory VF?","choices":["Vasopressin","ECMO alert","Procainamide","Esmolol"],"answer":1,"why":"ECMO alert for refractory VF was added.","page":391,"deck":"s16"},{"id":"s16q03","q":"June 2026 post-ROSC MAP target?","choices":["55–60","60–65","65–70","70–80"],"answer":2,"why":"Post-ROSC MAP criteria set to 65–70.","page":393,"deck":"s16"},{"id":"s16q04","q":"The 2026 update made what first-line for intubation?","choices":["Bougie","Direct laryngoscopy","Video laryngoscopy","Nasal intubation"],"answer":2,"why":"Video laryngoscopy first for all intubations.","page":391,"deck":"s16"}],"defaultSrc":"flfr26"};
